282	async fn run_latency_test(servers: &[crate::config::DnsServer]) -> Vec<DnsLatencyResult> {
283	    let mut results = Vec::new();
284	
285	    // 创建优化的 HTTP 客户端（连接池）
286	    let http_client = reqwest::Client::builder()
287	        .timeout(std::time::Duration::from_secs(3))
288	        .pool_max_idle_per_host(8)
289	        .pool_idle_timeout(std::time::Duration::from_secs(90))
290	        .build()
291	        .unwrap_or_default();
292	
293	    for server in servers {
294	        let name = server.name.clone();
295	        let ip = server.ip.clone();
296	        let addr = format!("{}:{}", server.ip, server.port);
297	
298	        // 构造DNS查询请求 (查询 example.com A记录)
299	        let query = build_dns_query("example.com");
300	
301	        let start = std::time::Instant::now();
302	        let result = match server.protocol {
303	            crate::config::DnsProtocol::Udp | crate::config::DnsProtocol::Tcp => {
304	                // UDP/TCP 测试
305	                match tokio::net::UdpSocket::bind("0.0.0.0:0").await {
306	                    Ok(socket) => {
307	                        if let Err(e) = socket.connect(&addr).await {
308	                            Err(format!("连接失败: {}", e))
309	                        } else {
310	                            match socket.send(&query).await {
311	                                Ok(_) => {
312	                                    let mut buf = vec![0u8; 512];
313	                                    match tokio::time::timeout(
314	                                        std::time::Duration::from_secs(2),
315	                                        socket.recv(&mut buf),
316	                                    )
317	                                    .await
318	                                    {
319	                                        Ok(Ok(len)) => Ok(buf[..len].to_vec()),
320	                                        Ok(Err(e)) => Err(format!("接收失败: {}", e)),
321	                                        Err(_) => Err("超时".to_string()),
322	                                    }
323	                                }
324	                                Err(e) => Err(format!("发送失败: {}", e)),
325	                            }
326	                        }
327	                    }
328	                    Err(e) => Err(format!("绑定失败: {}", e)),
329	                }
330	            }
331	            crate::config::DnsProtocol::Doh => {
332	                // DoH 测试 - 复用连接池
333	                let url = server
334	                    .doh_url
335	                    .as_deref()
336	                    .unwrap_or("https://cloudflare-dns.com/dns-query");
337	                match http_client
338	                    .post(url)
339	                    .header("Content-Type", "application/dns-message")
340	                    .header("Accept", "application/dns-message")
341	                    .body(query.clone())
342	                    .send()
343	                    .await
344	                {
345	                    Ok(resp) => match resp.bytes().await {
346	                        Ok(bytes) => Ok(bytes.to_vec()),
347	                        Err(e) => Err(format!("读取响应失败: {}", e)),
348	                    },
349	                    Err(e) => Err(format!("请求失败: {}", e)),
350	                }
351	            }
352	            crate::config::DnsProtocol::Dot => {
353	                // DoT 测试 - 使用 TLS 连接
354	                let dot_port = if server.port == 53 { 853 } else { server.port };
355	                test_dot_connection(&server.ip, dot_port, &query).await
356	            }
357	        };
358	
359	        let latency = start.elapsed().as_millis() as u64;
360	
361	        match result {
362	            Ok(_) => {
363	                results.push(DnsLatencyResult {
364	                    name,
365	                    ip,
366	                    latency_ms: Some(latency),
367	                    error: None,
368	                });
369	            }
370	            Err(e) => {
371	                results.push(DnsLatencyResult {
372	                    name,
373	                    ip,
374	                    latency_ms: None,
375	                    error: Some(e),
376	                });
377	            }
378	        }
379	    }
380	
381	    // 按延迟排序
382	    results.sort_by(|a, b| {
383	        a.latency_ms
384	            .unwrap_or(u64::MAX)
385	            .cmp(&b.latency_ms.unwrap_or(u64::MAX))
386	    });
387	
388	    results
389	}
