    in property <bool> enable-tun: false;
    in property <string> tun-interface: "dns-proxy-tun";
    in property <string> tun-gateway: "10.0.0.1";
    in property <string> tun-dns: "10.0.0.1";
    in property <bool> enable-doh: false;
    in property <string> doh-url: "";
    in property <bool> enable-dot: false;

    callback save-advanced-settings();

    VerticalBox {
        padding: 24px;
        spacing: 16px;

        Text {
            text: "高级设置";
            font-size: 24px;
            font-weight: 700;
            color: Theme.text-primary;
        }

        // TUN模式配置
        GroupBox {
            title: "TUN 模式配置";

            VerticalLayout {
                spacing: 12px;
                padding: 16px;

                CheckBox {
                    text: "启用 TUN 模式（全局代理）";
                    checked: enable-tun;
                }

                HorizontalLayout {
                    spacing: 12px;

                    Text {
                        text: "接口名称:";
                        vertical-alignment: center;
                        color: Theme.text-primary;
                    }

                    LineEdit {
                        text: tun-interface;
                        width: 200px;
                    }
                }

                HorizontalLayout {
                    spacing: 12px;

                    Text {
                        text: "网关地址:";
                        vertical-alignment: center;
                        color: Theme.text-primary;
                    }

                    LineEdit {
                        text: tun-gateway;
                        width: 200px;
                    }
                }

                HorizontalLayout {
                    spacing: 12px;

                    Text {
                        text: "DNS 地址:";
                        vertical-alignment: center;
                        color: Theme.text-primary;
                    }

                    LineEdit {
                        text: tun-dns;
                        width: 200px;
                    }
                }
            }
        }

        // DoH/DoT配置
        GroupBox {
            title: "加密 DNS 配置";

            VerticalLayout {
                spacing: 12px;
                padding: 16px;

                CheckBox {
                    text: "启用 DNS-over-HTTPS (DoH)";
                    checked: enable-doh;
                }

                if enable-doh: HorizontalLayout {
                    spacing: 12px;

                    Text {
                        text: "DoH URL:";
                        vertical-alignment: center;
                        color: Theme.text-primary;
                    }

                    LineEdit {
                        text: doh-url;
                        horizontal-stretch: 1;
                        placeholder-text: "https://cloudflare-dns.com/dns-query";
                    }
                }

                CheckBox {
                    text: "启用 DNS-over-TLS (DoT)";
                    checked: enable-dot;
                }
            }
        }

        // 保存按钮
        HorizontalLayout {
            alignment: end;

            Button {
                text: "保存设置";
                primary: true;
                width: 120px;
                clicked => { save-advanced-settings(); }
            }
        }
    }
}

// 主窗口
export component MainWindow inherits Window {
    title: "DNS Proxy";
    min-width: 1024px;
    min-height: 680px;
    background: Theme.bg-primary;
    icon: @image-url("../public/icon.png");

    // 状态属性
    in-out property <int> current-page: 0;
    in-out property <bool> dns-running: false;
    in-out property <bool> tun-running: false;
    in-out property <int> total-queries: 0;
    in-out property <int> blocked-queries: 0;
    in-out property <int> cached-queries: 0;
    in-out property <float> avg-latency: 0;
    in-out property <int> memory-usage: 0;
    in-out property <int> total-rules: 0;
    in-out property <int> block-rules: 0;
    in-out property <int> allow-rules: 0;
    in-out property <string> listen-port: "53";
    in-out property <bool> auto-start: true;
    in-out property <int> cache-size: 5000;
    in-out property <int> cache-ttl: 1800;
    in-out property <bool> enable-tun: false;
    in-out property <string> tun-interface: "dns-proxy-tun";
    in-out property <string> tun-gateway: "10.0.0.1";

    // 数据
    in-out property <[DnsLogEntry]> recent-logs;
    in-out property <[DnsLogEntry]> all-logs;
    in-out property <[string]> upstream-servers;
    in-out property <[string]> rule-list;

    // 回调
    callback start-dns();
    callback stop-dns();
    callback start-tun();
    callback stop-tun();
    callback save-dns-settings(string, bool, int, int);
    callback save-advanced-settings();
    callback clear-logs();
    callback export-logs();
    callback import-rules();
    callback export-rules();

    HorizontalLayout {
        // 侧边栏
        SideBar {
            current-page: current-page;
            page-changed(page) => {
                current-page = page;
            }
        }

        // 主内容区
        if current-page == 0: DashboardPage {
            total-queries: total-queries;
            blocked-queries: blocked-queries;
            cached-queries: cached-queries;
            avg-latency: avg-latency;
            dns-running: dns-running;
            tun-running: tun-running;
            memory-usage: memory-usage;
            recent-logs: recent-logs;
            start-dns => { start-dns(); }
            stop-dns => { stop-dns(); }
            start-tun => { start-tun(); }
            stop-tun => { stop-tun(); }
        }

        if current-page == 1: DnsSettingsPage {
            listen-port: listen-port;
            auto-start: auto-start;
            cache-size: cache-size;
            cache-ttl: cache-ttl;
            upstream-servers: upstream-servers;
            save-settings(port, auto, size, ttl) => {
                save-dns-settings(port, auto, size, ttl);
            }
        }

        if current-page == 2: RulesPage {
            total-rules: total-rules;
            block-rules: block-rules;
            allow-rules: allow-rules;
            rule-list: rule-list;
            import-rules => { import-rules(); }
            export-rules => { export-rules(); }
        }

        if current-page == 3: LogsPage {
            logs: all-logs;
            clear-logs => { clear-logs(); }
            export-logs => { export-logs(); }
        }

        if current-page == 4: AdvancedSettingsPage {
            enable-tun: enable-tun;
            tun-interface: tun-interface;
            tun-gateway: tun-gateway;
            save-advanced-settings => { save-advanced-settings(); }
        }
    }
}

toolUseResult.content:
import { Button, VerticalBox, HorizontalBox, LineEdit, ComboBox, CheckBox, ScrollView, GroupBox, StandardButton, Palette } from "std-widgets.slint";

// 颜色主题
global Theme {
    in-out property <color> bg-primary: #1e1e2e;
    in-out property <color> bg-secondary: #2d2d3f;
    in-out property <color> bg-card: #363649;
    in-out property <color> text-primary: #e0e0e0;
    in-out property <color> text-secondary: #a0a0a0;
    in-out property <color> accent: #6c5ce7;
    in-out property <color> accent-hover: #7c6cf7;
    in-out property <color> success: #00b894;
    in-out property <color> warning: #fdcb6e;
    in-out property <color> error: #e17055;
    in-out property <color> border: #404050;
}

// DNS日志条目
struct DnsLogEntry {
    timestamp: string,
    domain: string,
    query-type: string,
    response: string,
    status: string,
    latency: string,
}

// 侧边栏组件
component SideBar inherits Rectangle {
    in-out property <int> current-page: 0;
    callback page-changed(int);

    width: 200px;
    background: Theme.bg-secondary;

    VerticalBox {
        padding: 16px;
        spacing: 8px;

        // Logo区域
        Text {
            text: "DNS Proxy";
            font-size: 20px;
            font-weight: 700;
            color: Theme.text-primary;
            horizontal-alignment: center;
            padding-bottom: 16px;
        }

        // 版本号
        Text {
            text: "v1.0.0";
            font-size: 12px;
            color: Theme.text-secondary;
            horizontal-alignment: center;
            padding-bottom: 24px;
        }

        // 菜单项
        for page[index] in [
            { icon: "📊", label: "仪表盘" },
            { icon: "⚙️", label: "DNS 设置" },
            { icon: "📋", label: "规则管理" },
            { icon: "📡", label: "日志查看" },
            { icon: "🔧", label: "高级设置" },
        ]: Rectangle {
            height: 44px;
            background: current-page == index ? Theme.accent : transparent;
            border-radius: 8px;

            HorizontalLayout {
                alignment: center;
                spacing: 8px;
                padding-left: 16px;

                Text {
                    text: page.icon;
                    font-size: 16px;
                    vertical-alignment: center;
                }

                Text {
                    text: page.label;
                    font-size: 14px;
                    color: current-page == index ? white : Theme.text-primary;
                    vertical-alignment: center;
                }
            }

            touch := TouchArea {
                clicked => {
                    current-page = index;
                    page-changed(index);
                }
            }
        }
    }
}

// 状态指示灯
component StatusDot inherits Rectangle {
    in property <bool> active: false;
    width: 12px;
    height: 12px;
    border-radius: 6px;
    background: active ? Theme.success : Theme.error;
}

// 统计卡片
component StatCard inherits Rectangle {
    in property <string> title;
    in property <string> value;
    in property <string> subtitle;
    in property <color> value-color: Theme.text-primary;

    background: Theme.bg-card;
    border-radius: 12px;
    border-width: 1px;
    border-color: Theme.border;
    height: 100px;

    VerticalLayout {
        padding: 16px;
        spacing: 4px;

        Text {
            text: title;
            font-size: 12px;
            color: Theme.text-secondary;
        }

        Text {
            text: value;
            font-size: 28px;
            font-weight: 700;
            color: value-color;
        }

        if subtitle != "": Text {
            text: subtitle;
            font-size: 11px;
            color: Theme.text-secondary;
        }
    }
}

// 仪表盘页面
component DashboardPage inherits ScrollView {
    in property <int> total-queries: 0;
    in property <int> blocked-queries: 0;
    in property <int> cached-queries: 0;
    in property <float> avg-latency: 0;
    in property <bool> dns-running: false;
    in property <bool> tun-running: false;
    in property <int> memory-usage: 0;
    in property <[DnsLogEntry]> recent-logs;

    callback start-dns();
    callback stop-dns();
    callback start-tun();
    callback stop-tun();

    VerticalBox {
        padding: 24px;
        spacing: 16px;

        // 标题栏
        HorizontalLayout {
            Text {
                text: "仪表盘";
                font-size: 24px;
                font-weight: 700;
                color: Theme.text-primary;
                vertical-alignment: center;
            }

            Rectangle { horizontal-stretch: 1; }

            // DNS状态
            HorizontalLayout {
                spacing: 8px;
                alignment: center;

                StatusDot { active: dns-running; }

                Text {
                    text: dns-running ? "DNS 运行中" : "DNS 已停止";
                    font-size: 14px;
                    color: Theme.text-secondary;
                    vertical-alignment: center;
                }

                Button {
                    text: dns-running ? "停止" : "启动";
                    clicked => {
                        if dns-running {
                            stop-dns();
                        } else {
                            start-dns();
                        }
                    }
                }
            }

            // TUN状态
            HorizontalLayout {
                spacing: 8px;
                alignment: center;

                StatusDot { active: tun-running; }

                Text {
                    text: tun-running ? "TUN 运行中" : "TUN 已停止";
                    font-size: 14px;
                    color: Theme.text-secondary;
                    vertical-alignment: center;
                }

                Button {
                    text: tun-running ? "停止" : "启动";
                    clicked => {
                        if tun-running {
                            stop-tun();
                        } else {
                            start-tun();
                        }
                    }
                }
            }
        }

        // 统计卡片
        HorizontalLayout {
            spacing: 16px;

            StatCard {
                title: "总查询数";
                value: total-queries;
                horizontal-stretch: 1;
            }

            StatCard {
                title: "已阻止";
                value: blocked-queries;
                value-color: Theme.error;
                horizontal-stretch: 1;
            }

            StatCard {
                title: "缓存命中";
                value: cached-queries;
                value-color: Theme.success;
                horizontal-stretch: 1;
            }

            StatCard {
                title: "平均延迟";
                value: avg-latency + "ms";
                horizontal-stretch: 1;
            }

            StatCard {
                title: "内存占用";
                value: memory-usage + "MB";
                value-color: memory-usage > 100 ? Theme.warning : Theme.success;
                horizontal-stretch: 1;
            }
        }

        // 最近日志
        GroupBox {
            title: "最近查询";

            VerticalLayout {
                spacing: 4px;

                for log in recent-logs: Rectangle {
                    height: 32px;
                    background: Theme.bg-card;
                    border-radius: 4px;

                    HorizontalLayout {
                        padding-left: 12px;
                        padding-right: 12px;
                        spacing: 16px;

                        Text {
                            text: log.timestamp;
                            font-size: 12px;
                            color: Theme.text-secondary;
                            width: 80px;
                            vertical-alignment: center;
                        }

                        Text {
                            text: log.domain;
                            font-size: 13px;
                            color: Theme.text-primary;
                            horizontal-stretch: 1;
                            overflow: elide;
                            vertical-alignment: center;
                        }

                        Text {
                            text: log.query-type;
                            font-size: 12px;
                            color: Theme.text-secondary;
                            width: 40px;
                            vertical-alignment: center;
                        }

                        Text {
                            text: log.status;
                            font-size: 12px;
                            color: log.status == "已阻止" ? Theme.error : Theme.success;
                            width: 60px;
                            vertical-alignment: center;
                        }

                        Text {
                            text: log.latency;
                            font-size: 12px;
                            color: Theme.text-secondary;
                            width: 60px;
                            vertical-alignment: center;
                        }
                    }
                }
            }
        }
    }
}

// DNS设置页面
component DnsSettingsPage inherits ScrollView {
    in property <string> listen-port: "53";
    in property <bool> auto-start: true;
    in property <int> cache-size: 5000;
    in property <int> cache-ttl: 1800;
    in property <[string]> upstream-servers;

    callback save-settings(string, bool, int, int);

    VerticalBox {
        padding: 24px;
        spacing: 16px;

        Text {
            text: "DNS 设置";
            font-size: 24px;
            font-weight: 700;
            color: Theme.text-primary;
        }

        // 监听配置
        GroupBox {
            title: "监听配置";

            VerticalLayout {
                spacing: 12px;
                padding: 16px;

                HorizontalLayout {
                    spacing: 12px;
                    alignment: start;

                    Text {
                        text: "监听端口:";
                        vertical-alignment: center;
                        color: Theme.text-primary;
                    }

                    LineEdit {
                        text: listen-port;
                        width: 100px;
                    }

                    CheckBox {
                        text: "开机自动启动";
                        checked: auto-start;
                    }
                }
            }
        }

        // 缓存配置
        GroupBox {
            title: "缓存配置";

            VerticalLayout {
                spacing: 12px;
                padding: 16px;

                HorizontalLayout {
                    spacing: 24px;

                    HorizontalLayout {
                        spacing: 8px;

                        Text {
                            text: "缓存大小:";
                            vertical-alignment: center;
                            color: Theme.text-primary;
                        }

                        LineEdit {
                            text: cache-size;
                            width: 100px;
                        }

                        Text {
                            text: "条";
                            vertical-alignment: center;
                            color: Theme.text-secondary;
                        }
                    }

                    HorizontalLayout {
                        spacing: 8px;

                        Text {
                            text: "缓存TTL:";
                            vertical-alignment: center;
                            color: Theme.text-primary;
                        }

                        LineEdit {
                            text: cache-ttl;
                            width: 100px;
                        }

                        Text {
                            text: "秒";
                            vertical-alignment: center;
                            color: Theme.text-secondary;
                        }
                    }
                }
            }
        }

        // 上游服务器
        GroupBox {
            title: "上游 DNS 服务器";

            VerticalLayout {
                spacing: 8px;
                padding: 16px;

                for server in upstream-servers: Rectangle {
                    height: 40px;
                    background: Theme.bg-card;
                    border-radius: 6px;

                    HorizontalLayout {
                        padding-left: 12px;
                        padding-right: 12px;

                        Text {
                            text: server;
                            font-size: 14px;
                            color: Theme.text-primary;
                            vertical-alignment: center;
                            horizontal-stretch: 1;
                        }

                        Button {
                            text: "删除";
                            width: 60px;
                        }
                    }
                }

                Button {
                    text: "添加服务器";
                    width: 120px;
                }
            }
        }

        // 保存按钮
        HorizontalLayout {
            alignment: end;

            Button {
                text: "保存设置";
                primary: true;
                width: 120px;
                clicked => {
                    save-settings(listen-port, auto-start, cache-size, cache-ttl);
                }
            }
        }
    }
}

// 规则管理页面
component RulesPage inherits ScrollView {
    in property <int> total-rules: 0;
    in property <int> block-rules: 0;
    in property <int> allow-rules: 0;
    in property <[string]> rule-list;

    callback import-rules();
    callback export-rules();

    VerticalBox {
        padding: 24px;
        spacing: 16px;

        HorizontalLayout {
            Text {
                text: "规则管理";
                font-size: 24px;
                font-weight: 700;
                color: Theme.text-primary;
                vertical-alignment: center;
            }

            Rectangle { horizontal-stretch: 1; }

            Button {
                text: "导入规则";
                clicked => { import-rules(); }
            }

            Button {
                text: "导出规则";
                clicked => { export-rules(); }
            }
        }

        // 规则统计
        HorizontalLayout {
            spacing: 16px;

            StatCard {
                title: "总规则数";
                value: total-rules;
                horizontal-stretch: 1;
            }

            StatCard {
                title: "阻止规则";
                value: block-rules;
                value-color: Theme.error;
                horizontal-stretch: 1;
            }

            StatCard {
                title: "允许规则";
                value: allow-rules;
                value-color: Theme.success;
                horizontal-stretch: 1;
            }
        }

        // 规则列表
        GroupBox {
            title: "规则列表";

            VerticalLayout {
                spacing: 4px;

                for rule in rule-list: Rectangle {
                    height: 36px;
                    background: Theme.bg-card;
                    border-radius: 4px;

                    HorizontalLayout {
                        padding-left: 12px;
                        padding-right: 12px;

                        Text {
                            text: rule;
                            font-size: 13px;
                            color: Theme.text-primary;
                            vertical-alignment: center;
                            horizontal-stretch: 1;
                            overflow: elide;
                        }

                        Button {
                            text: "删除";
                            width: 60px;
                        }
                    }
                }
            }
        }
    }
}

// 日志页面
component LogsPage inherits ScrollView {
    in property <[DnsLogEntry]> logs;
    in property <bool> auto-scroll: true;

    callback clear-logs();
    callback export-logs();

    VerticalBox {
        padding: 24px;
        spacing: 16px;

        HorizontalLayout {
            Text {
                text: "DNS 查询日志";
                font-size: 24px;
                font-weight: 700;
                color: Theme.text-primary;
                vertical-alignment: center;
            }

            Rectangle { horizontal-stretch: 1; }

            CheckBox {
                text: "自动滚动";
                checked: auto-scroll;
            }

            Button {
                text: "清空日志";
                clicked => { clear-logs(); }
            }

            Button {
                text: "导出日志";
                clicked => { export-logs(); }
            }
        }

        // 日志表格
        Rectangle {
            background: Theme.bg-card;
            border-radius: 8px;
            border-width: 1px;
            border-color: Theme.border;

            VerticalLayout {
                // 表头
                Rectangle {
                    height: 36px;
                    background: Theme.bg-secondary;
                    border-radius: 8px;

                    HorizontalLayout {
                        padding-left: 12px;
                        padding-right: 12px;
                        spacing: 16px;

                        Text {
                            text: "时间";
                            font-size: 12px;
                            font-weight: 600;
                            color: Theme.text-secondary;
                            width: 80px;
                            vertical-alignment: center;
                        }

                        Text {
                            text: "域名";
                            font-size: 12px;
                            font-weight: 600;
                            color: Theme.text-secondary;
                            horizontal-stretch: 1;
                            vertical-alignment: center;
                        }

                        Text {
                            text: "类型";
                            font-size: 12px;
                            font-weight: 600;
                            color: Theme.text-secondary;
                            width: 50px;
                            vertical-alignment: center;
                        }

                        Text {
                            text: "响应";
                            font-size: 12px;
                            font-weight: 600;
                            color: Theme.text-secondary;
                            width: 120px;
                            vertical-alignment: center;
                        }

                        Text {
                            text: "状态";
                            font-size: 12px;
                            font-weight: 600;
                            color: Theme.text-secondary;
                            width: 60px;
                            vertical-alignment: center;
                        }

                        Text {
                            text: "延迟";
                            font-size: 12px;
                            font-weight: 600;
                            color: Theme.text-secondary;
                            width: 60px;
                            vertical-alignment: center;
                        }
                    }
                }

                // 日志行
                for log in logs: Rectangle {
                    height: 32px;

                    HorizontalLayout {
                        padding-left: 12px;
                        padding-right: 12px;
                        spacing: 16px;

                        Text {
                            text: log.timestamp;
                            font-size: 12px;
                            color: Theme.text-secondary;
                            width: 80px;
                            vertical-alignment: center;
                        }

                        Text {
                            text: log.domain;
                            font-size: 13px;
                            color: Theme.text-primary;
                            horizontal-stretch: 1;
                            overflow: elide;
                            vertical-alignment: center;
                        }

                        Text {
                            text: log.query-type;
                            font-size: 12px;
                            color: Theme.text-secondary;
                            width: 50px;
                            vertical-alignment: center;
                        }

                        Text {
                            text: log.response;
                            font-size: 12px;
                            color: Theme.text-primary;
                            width: 120px;
                            overflow: elide;
                            vertical-alignment: center;
                        }

                        Text {
                            text: log.status;
                            font-size: 12px;
                            color: log.status == "已阻止" ? Theme.error : Theme.success;
                            width: 60px;
                            vertical-alignment: center;
                        }

                        Text {
                            text: log.latency;
                            font-size: 12px;
                            color: Theme.text-secondary;
                            width: 60px;
                            vertical-alignment: center;
                        }
                    }
                }
            }
        }
    }
}

// 高级设置页面
component AdvancedSettingsPage inherits ScrollView {
    in property <bool> enable-tun: false;
    in property <string> tun-interface: "dns-proxy-tun";
    in property <string> tun-gateway: "10.0.0.1";
    in property <string> tun-dns: "10.0.0.1";
    in property <bool> enable-doh: false;
    in property <string> doh-url: "";
    in property <bool> enable-dot: false;

    callback save-advanced-settings();

    VerticalBox {
        padding: 24px;
        spacing: 16px;

        Text {
            text: "高级设置";
            font-size: 24px;
            font-weight: 700;
            color: Theme.text-primary;
        }

        // TUN模式配置
        GroupBox {
            title: "TUN 模式配置";

            VerticalLayout {
                spacing: 12px;
                padding: 16px;

                CheckBox {
                    text: "启用 TUN 模式（全局代理）";
                    checked: enable-tun;
                }

                HorizontalLayout {
                    spacing: 12px;

                    Text {
                        text: "接口名称:";
                        vertical-alignment: center;
                        color: Theme.text-primary;
                    }

                    LineEdit {
                        text: tun-interface;
                        width: 200px;
                    }
                }

                HorizontalLayout {
                    spacing: 12px;

                    Text {
                        text: "网关地址:";
                        vertical-alignment: center;
                        color: Theme.text-primary;
                    }

                    LineEdit {
                        text: tun-gateway;
                        width: 200px;
                    }
                }

                HorizontalLayout {
                    spacing: 12px;

                    Text {
                        text: "DNS 地址:";
                        vertical-alignment: center;
                        color: Theme.text-primary;
                    }

                    LineEdit {
                        text: tun-dns;
                        width: 200px;
                    }
                }
            }
        }

        // DoH/DoT配置
        GroupBox {
            title: "加密 DNS 配置";

            VerticalLayout {
                spacing: 12px;
                padding: 16px;

                CheckBox {
                    text: "启用 DNS-over-HTTPS (DoH)";
                    checked: enable-doh;
                }

                if enable-doh: HorizontalLayout {
                    spacing: 12px;

                    Text {
                        text: "DoH URL:";
                        vertical-alignment: center;
                        color: Theme.text-primary;
                    }

                    LineEdit {
                        text: doh-url;
                        horizontal-stretch: 1;
                        placeholder-text: "https://cloudflare-dns.com/dns-query";
                    }
                }

                CheckBox {
                    text: "启用 DNS-over-TLS (DoT)";
                    checked: enable-dot;
                }
            }
        }

        // 保存按钮
        HorizontalLayout {
            alignment: end;

            Button {
                text: "保存设置";
                primary: true;
                width: 120px;
                clicked => { save-advanced-settings(); }
            }
        }
    }
}

// 主窗口
export component MainWindow inherits Window {
    title: "DNS Proxy";
    min-width: 1024px;
    min-height: 680px;
    background: Theme.bg-primary;
    icon: @image-url("../public/icon.png");

    // 状态属性
    in-out property <int> current-page: 0;
    in-out property <bool> dns-running: false;
    in-out property <bool> tun-running: false;
    in-out property <int> total-queries: 0;
    in-out property <int> blocked-queries: 0;
    in-out property <int> cached-queries: 0;
    in-out property <float> avg-latency: 0;
    in-out property <int> memory-usage: 0;
    in-out property <int> total-rules: 0;
    in-out property <int> block-rules: 0;
    in-out property <int> allow-rules: 0;
    in-out property <string> listen-port: "53";
    in-out property <bool> auto-start: true;
    in-out property <int> cache-size: 5000;
    in-out property <int> cache-ttl: 1800;
    in-out property <bool> enable-tun: false;
    in-out property <string> tun-interface: "dns-proxy-tun";
    in-out property <string> tun-gateway: "10.0.0.1";

    // 数据
    in-out property <[DnsLogEntry]> recent-logs;
    in-out property <[DnsLogEntry]> all-logs;
    in-out property <[string]> upstream-servers;
    in-out property <[string]> rule-list;

    // 回调
    callback start-dns();
    callback stop-dns();
    callback start-tun();
    callback stop-tun();
    callback save-dns-settings(string, bool, int, int);
    callback save-advanced-settings();
    callback clear-logs();
    callback export-logs();
    callback import-rules();
    callback export-rules();

    HorizontalLayout {
        // 侧边栏
        SideBar {
            current-page: current-page;
            page-changed(page) => {
                current-page = page;
            }
        }

        // 主内容区
        if current-page == 0: DashboardPage {
            total-queries: total-queries;
            blocked-queries: blocked-queries;
            cached-queries: cached-queries;
            avg-latency: avg-latency;
            dns-running: dns-running;
            tun-running: tun-running;
            memory-usage: memory-usage;
            recent-logs: recent-logs;
            start-dns => { start-dns(); }
            stop-dns => { stop-dns(); }
            start-tun => { start-tun(); }
            stop-tun => { stop-tun(); }
        }

        if current-page == 1: DnsSettingsPage {
            listen-port: listen-port;
            auto-start: auto-start;
            cache-size: cache-size;
            cache-ttl: cache-ttl;
            upstream-servers: upstream-servers;
            save-settings(port, auto, size, ttl) => {
                save-dns-settings(port, auto, size, ttl);
            }
        }

        if current-page == 2: RulesPage {
            total-rules: total-rules;
            block-rules: block-rules;
            allow-rules: allow-rules;
            rule-list: rule-list;
            import-rules => { import-rules(); }
            export-rules => { export-rules(); }
        }

        if current-page == 3: LogsPage {
            logs: all-logs;
            clear-logs => { clear-logs(); }
            export-logs => { export-logs(); }
        }

        if current-page == 4: AdvancedSettingsPage {
            enable-tun: enable-tun;
            tun-interface: tun-interface;
            tun-gateway: tun-gateway;
            save-advanced-settings => { save-advanced-settings(); }
        }
    }
}

