15	/// 缓存统计信息
16	#[derive(Debug, Clone, serde::Serialize)]
17	pub struct CacheStats {
18	    /// 总查询次数
19	    pub total_queries: u64,
20	    /// 缓存命中次数
21	    pub cache_hits: u64,
22	    /// 缓存未命中次数
23	    pub cache_misses: u64,
24	    /// 命中率 (0.0 - 1.0)
