32	/// LRU DNS 缓存
33	pub struct DnsCache {
34	    entries: Mutex<LruCache<String, CacheEntry>>,
35	    max_size: usize,
36	    default_ttl: Duration,
37	    // 统计信息
38	    total_queries: Mutex<u64>,
39	    cache_hits: Mutex<u64>,
40	    cache_misses: Mutex<u64>,
41	}
42	
43	impl DnsCache {
44	    pub fn new(max_size: usize, default_ttl: Duration) -> Self {
45	        let capacity = NonZeroUsize::new(max_size.max(1)).unwrap_or(NonZeroUsize::new(1000).unwrap());
46	        Self {
47	            entries: Mutex::new(LruCache::new(capacity)),
48	            max_size,
49	            default_ttl,
50	            total_queries: Mutex::new(0),
51	            cache_hits: Mutex::new(0),
52	            cache_misses: Mutex::new(0),
53	        }
54	    }
55	
56	    /// 从缓存获取条目
