1	use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};
2	use tracing::debug;
3	
4	/// EDNS Client Subnet (ECS) 配置
5	#[derive(Debug, Clone)]
6	pub struct EcsConfig {
7	    /// 是否启用 ECS
8	    pub enabled: bool,
9	    /// 客户端 IP 地址（如果为 None，则从请求中推断）
10	    pub client_ip: Option<IpAddr>,
11	    /// IPv4 源掩码长度（默认 24，即 /24 子网）
12	    pub ipv4_source_mask: u8,
13	    /// IPv6 源掩码长度（默认 56，即 /56 子网）
14	    pub ipv6_source_mask: u8,
15	}
16	
17	impl Default for EcsConfig {
18	    fn default() -> Self {
19	        Self {
20	            enabled: false,
21	            client_ip: None,
22	            ipv4_source_mask: 24,
23	            ipv6_source_mask: 56,
24	        }
25	    }
26	}
27	
28	/// EDNS0 OPT 记录类型
29	const OPT_TYPE: u16 = 41;
30	/// ECS Option Code
31	const ECS_OPTION_CODE: u16 = 8;
32	/// 默认 UDP payload size
33	const UDP_PAYLOAD_SIZE: u16 = 4096;
34	
35	/// 在 DNS 查询包中注入 ECS 信息
36	///
37	/// # 参数
38	/// - `query_bytes`: 原始 DNS 查询包
39	/// - `client_ip`: 客户端 IP 地址
40	/// - `source_mask`: 源掩码长度
41	///
42	/// # 返回
43	/// 注入 ECS 后的 DNS 查询包
44	pub fn inject_ecs(query_bytes: &[u8], client_ip: IpAddr, source_mask: u8) -> Vec<u8> {
45	    let mut packet = query_bytes.to_vec();
46	
47	    // 构建 EDNS0 OPT 记录
48	    let opt_record = build_opt_record(client_ip, source_mask);
49	
50	    // 追加到 DNS 包末尾
51	    packet.extend_from_slice(&opt_record);
52	
53	    // 更新 Additional Count（第 10-11 字节）
54	    if packet.len() >= 12 {
55	        let additional_count = u16::from_be_bytes([packet[10], packet[11]]);
56	        packet[10] = ((additional_count + 1) >> 8) as u8;
57	        packet[11] = ((additional_count + 1) & 0xFF) as u8;
58	    }
59	
60	    debug!("已注入 ECS: client_ip={}, mask=/{}/", client_ip, source_mask);
61	    packet
62	}
63	
64	/// 构建 EDNS0 OPT 记录
65	///
66	/// OPT 记录格式：
67	/// - Name: 0x00 (root)
68	/// - Type: 41 (OPT)
69	/// - Class: UDP payload size
70	/// - TTL: Extended RCODE (8 bits) + Version (8 bits) + DO bit (1 bit) + Z (15 bits)
71	/// - RDLENGTH: RDATA 长度
72	/// - RDATA: EDNS options
73	fn build_opt_record(client_ip: IpAddr, source_mask: u8) -> Vec<u8> {
74	    let mut record = Vec::new();
75	
76	    // Name: root (0x00)
77	    record.push(0x00);
78	
79	    // Type: OPT (41)
80	    record.extend_from_slice(&OPT_TYPE.to_be_bytes());
81	
82	    // Class: UDP payload size
83	    record.extend_from_slice(&UDP_PAYLOAD_SIZE.to_be_bytes());
84	
85	    // TTL: Extended RCODE + Version + Flags
86	    // Extended RCODE: 0, Version: 0, DO bit: 0, Z: 0
87	    record.extend_from_slice(&[0x00, 0x00, 0x00, 0x00]);
88	
89	    // 构建 ECS Option
90	    let ecs_option = build_ecs_option(client_ip, source_mask);
91	
92	    // RDLENGTH
93	    record.extend_from_slice(&(ecs_option.len() as u16).to_be_bytes());
94	
95	    // RDATA
96	    record.extend_from_slice(&ecs_option);
97	
98	    record
99	}
100	
101	/// 构建 ECS Option
102	///
103	/// ECS Option 格式：
104	/// - Option Code: 8 (Client Subnet)
105	/// - Option Length: 数据长度
106	/// - Family: 1 (IPv4) 或 2 (IPv6)
107	/// - Source Netmask: 源掩码长度
108	/// - Scope Netmask: 作用域掩码长度（查询时为 0）
109	/// - Address: 客户端 IP 地址（按掩码截断，填充到字节边界）
110	fn build_ecs_option(client_ip: IpAddr, source_mask: u8) -> Vec<u8> {
111	    let mut option = Vec::new();
112	
113	    // Option Code: ECS (8)
114	    option.extend_from_slice(&ECS_OPTION_CODE.to_be_bytes());
115	
116	    match client_ip {
117	        IpAddr::V4(ipv4) => {
118	            let mask = source_mask.min(32);
119	            let addr_bytes = truncate_ipv4(ipv4, mask);
120	            let option_data_len = 4 + addr_bytes.len(); // Family(2) + Mask(1) + Scope(1) + Address
121	
122	            // Option Length
123	            option.extend_from_slice(&(option_data_len as u16).to_be_bytes());
124	
125	            // Family: IPv4 (1)
126	            option.extend_from_slice(&1u16.to_be_bytes());
127	
128	            // Source Netmask
129	            option.push(mask);
130	
131	            // Scope Netmask (查询时为 0)
132	            option.push(0);
133	
134	            // Address
135	            option.extend_from_slice(&addr_bytes);
136	        }
137	        IpAddr::V6(ipv6) => {
138	            let mask = source_mask.min(128);
139	            let addr_bytes = truncate_ipv6(ipv6, mask);
140	            let option_data_len = 4 + addr_bytes.len();
141	
142	            // Option Length
143	            option.extend_from_slice(&(option_data_len as u16).to_be_bytes());
144	
145	            // Family: IPv6 (2)
146	            option.extend_from_slice(&2u16.to_be_bytes());
147	
148	            // Source Netmask
149	            option.push(mask);
150	
151	            // Scope Netmask (查询时为 0)
152	            option.push(0);
153	
154	            // Address
155	            option.extend_from_slice(&addr_bytes);
156	        }
157	    }
158	
159	    option
160	}
161	
162	/// 截断 IPv4 地址到指定掩码长度
163	///
164	/// 返回截断后的字节数组（填充到字节边界）
165	fn truncate_ipv4(ip: Ipv4Addr, mask: u8) -> Vec<u8> {
166	    let octets = ip.octets();
167	    let full_bytes = (mask / 8) as usize;
168	    let remaining_bits = mask % 8;
169	
170	    let mut result = Vec::new();
171	
172	    // 复制完整的字节
173	    for i in 0..full_bytes.min(4) {
174	        result.push(octets[i]);
175	    }
