                                latency: format!("{}ms", log.latency_ms).into(),
                            })
                            .collect::<Vec<_>>(),
                    ));

                let upstream_servers_model: slint::ModelRc<slint::SharedString> =
                    slint::ModelRc::from(slint::VecModel::from(upstream_servers));

                let memory_usage = get_memory_usage();

                ui.set_dns_running(is_running);
                ui.set_tun_running(tun_running);
                ui.set_total_queries(total as i32);
                ui.set_blocked_queries(blocked as i32);
                ui.set_cached_queries(cached as i32);
                ui.set_avg_latency(avg_latency as f32);
                ui.set_memory_usage(memory_usage as i32);
                ui.set_total_rules(total_rules);
                ui.set_block_rules(block_rules);
                ui.set_allow_rules(allow_rules);
                ui.set_recent_logs(recent_logs);
                ui.set_all_logs(all_logs);
                ui.set_upstream_servers(upstream_servers_model);
                ui.set_listen_port(listen_port.into());
                ui.set_auto_start(auto_start);
                ui.set_cache_size(cache_size);
                ui.set_cache_ttl(cache_ttl);
            });
        },
    );

    ui.run()?;
    Ok(())
}

fn setup_callbacks(ui: &MainWindow, state: Arc<AppState>) {
    // 启动 DNS
    let state_dns = state.clone();
    ui.on_start_dns(move || {
        let server = state_dns.server.clone();
        tokio::spawn(async move {
            let mut server = server.lock().await;
            if let Err(e) = server.start().await {
                tracing::error!("启动DNS服务失败: {}", e);
            }
        });
    });

    // 停止 DNS
    let state_dns = state.clone();
    ui.on_stop_dns(move || {
        let server = state_dns.server.clone();
        tokio::spawn(async move {
            let mut server = server.lock().await;
            server.stop().await;
        });
    });

    // 启动 TUN
    let state_tun = state.clone();
    ui.on_start_tun(move || {
        let tun_device = state_tun.tun_device.clone();
        let tun_config = state_tun.tun_config.clone();
        let server = state_tun.server.clone();
        tokio::spawn(async move {
            let config = tun_config.lock().await.clone();
            let mut tun = tun_device.lock().await;
            *tun = TunDevice::new(config);
            match tun.start().await {
                Ok(()) => {
                    tracing::info!("TUN已启动");
                    let tun_clone = tun_device.clone();
                    drop(tun);
                    let server = server.lock().await;
                    let handler = server.get_dns_handler();
                    let interceptor = DnsInterceptor::new(tun_clone);
                    interceptor.start(handler).await;
                }
                Err(e) => {
                    tracing::error!("启动TUN失败: {}", e);
                }
            }
        });
    });

    // 停止 TUN
    let state_tun = state.clone();
    ui.on_stop_tun(move || {
        let tun_device = state_tun.tun_device.clone();
        tokio::spawn(async move {
            let mut tun = tun_device.lock().await;
            tun.stop().await;
        });
    });

    // 保存 DNS 设置
    let state_save = state.clone();
    ui.on_save_dns_settings(move |port, auto_start, cache_size, cache_ttl| {
        let config = state_save.config.clone();
        let server = state_save.server.clone();
        tokio::spawn(async move {
            let mut cfg = config.lock().await;
            cfg.proxy.listen_port = port.to_string().parse().unwrap_or(53);
            cfg.proxy.auto_start = auto_start;
            cfg.proxy.cache_size = cache_size as usize;
            cfg.proxy.cache_ttl = cache_ttl as u64;
            let _ = cfg.save();
            drop(cfg);

            // 重启服务器
            let mut server = server.lock().await;
            if server.is_running().await {
                server.stop().await;
                tokio::time::sleep(std::time::Duration::from_millis(300)).await;
                let config = config.lock().await.clone();
                *server = DnsServer::new(config);
                let _ = server.start().await;
            }
        });
    });

    // 保存高级设置
    let _state_advanced = state.clone();
    ui.on_save_advanced_settings(move || {
        // TODO: 从 UI 获取设置值并保存
    });

    // 清空日志
    let state_logs = state.clone();
    ui.on_clear_logs(move || {
        let server = state_logs.server.clone();
        tokio::spawn(async move {
            let server = server.lock().await;
            server.clear_logs();
        });
    });

    // 导出日志
    ui.on_export_logs(|| {
        // TODO: 实现日志导出
    });

    // 导入规则
    ui.on_import_rules(|| {
        // TODO: 实现规则导入
    });

    // 导出规则
    ui.on_export_rules(|| {
        // TODO: 实现规则导出
    });
}

fn get_memory_usage() -> usize {
    // 获取当前进程内存使用（MB）
    #[cfg(target_os = "windows")]
    {
        use windows::Win32::System::ProcessStatus::{GetProcessMemoryInfo, PROCESS_MEMORY_COUNTERS};
        use windows::Win32::System::Threading::GetCurrentProcess;

        unsafe {
            let mut counters = PROCESS_MEMORY_COUNTERS::default();
            if GetProcessMemoryInfo(
                GetCurrentProcess(),
                &mut counters,
                std::mem::size_of::<PROCESS_MEMORY_COUNTERS>() as u32,
            )
            .is_ok()
            {
                return (counters.WorkingSetSize / 1024 / 1024) as usize;
            }
        }
    }

    // 默认返回 0
    0
}

