mod config;
mod dns;
mod tun;

use config::AppConfig;
use dns::server::DnsServer;
use slint::Timer;
use std::sync::Arc;
use tokio::sync::{mpsc, Mutex};
use tun::device::TunDevice;
use tun::dns_intercept::DnsInterceptor;
use tun::TunConfig;

slint::include_modules!();

struct AppState {
    server: Arc<Mutex<DnsServer>>,
    config: Arc<Mutex<AppConfig>>,
    tun_device: Arc<Mutex<TunDevice>>,
    tun_config: Arc<Mutex<TunConfig>>,
}

#[derive(Clone)]
struct UiState {
    dns_running: bool,
    tun_running: bool,
    total_queries: i32,
    blocked_queries: i32,
    cached_queries: i32,
    avg_latency: f32,
    memory_usage: i32,
    total_rules: i32,
    block_rules: i32,
    allow_rules: i32,
    listen_port: String,
    auto_start: bool,
    cache_size: i32,
    cache_ttl: i32,
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    // 初始化日志
    tracing_subscriber::fmt()
        .with_env_filter(
            tracing_subscriber::EnvFilter::try_from_default_env()
                .unwrap_or_else(|_| tracing_subscriber::EnvFilter::new("info")),
        )
        .init();

    // 加载配置
    let config = AppConfig::load();
    let server = DnsServer::new(config.clone());
    let tun_config = config.tun.clone();
    let tun_device = TunDevice::new(tun_config.clone());

    let state = Arc::new(AppState {
        server: Arc::new(Mutex::new(server)),
        config: Arc::new(Mutex::new(config.clone())),
        tun_device: Arc::new(Mutex::new(tun_device)),
        tun_config: Arc::new(Mutex::new(tun_config)),
    });

    // 创建 Slint UI
    let ui = MainWindow::new()?;

    // 设置回调
    setup_callbacks(&ui, state.clone());

    // 创建 channel 用于更新 UI
    let (ui_sender, ui_receiver) = mpsc::channel::<UiState>(100);

    // 启动后台任务更新 UI 状态
    let state_timer = state.clone();
    let ui_sender_clone = ui_sender.clone();
    tokio::spawn(async move {
        loop {
            tokio::time::sleep(std::time::Duration::from_secs(1)).await;

            let server = state_timer.server.lock().await;
            let (total, blocked, cached, avg_latency) = server.get_stats();
            let is_running = server.is_running().await;
            drop(server);

            let tun = state_timer.tun_device.lock().await;
            let tun_running = tun.is_running().await;
            drop(tun);

            let config = state_timer.config.lock().await;
            let total_rules = config.rules.len() as i32;
            let block_rules = config
                .rules
                .iter()
                .filter(|r| {
                    r.action == config::RuleAction::Block
                        || r.action == config::RuleAction::BlockNull
                        || r.action == config::RuleAction::BlockNxdomain
                })
                .count() as i32;
            let allow_rules = config
                .rules
                .iter()
                .filter(|r| r.action == config::RuleAction::Allow)
                .count() as i32;
            let listen_port = config.proxy.listen_port.to_string();
            let auto_start = config.proxy.auto_start;
            let cache_size = config.proxy.cache_size as i32;
            let cache_ttl = config.proxy.cache_ttl as i32;
            drop(config);

            let ui_state = UiState {
                dns_running: is_running,
                tun_running,
                total_queries: total as i32,
                blocked_queries: blocked as i32,
                cached_queries: cached as i32,
                avg_latency: avg_latency as f32,
                memory_usage: 0,
                total_rules,
                block_rules,
                allow_rules,
                listen_port,
                auto_start,
                cache_size,
                cache_ttl,
            };

            if ui_sender_clone.send(ui_state).await.is_err() {
                break;
            }
        }
    });

    // 启动日志更新任务
    let state_logs = state.clone();
    let ui_weak = ui.as_weak();
    tokio::spawn(async move {
        let mut interval = tokio::time::interval(std::time::Duration::from_millis(500));
        loop {
            interval.tick().await;

            let server = state_logs.server.lock().await;
            let logs = server.get_logs();
            drop(server);

            let config = state_logs.config.lock().await;
            let upstream_servers: Vec<slint::SharedString> = config
                .upstream
                .iter()
                .map(|s| format!("{} ({}:{})", s.name, s.ip, s.port).into())
                .collect();
            drop(config);

            let recent_logs = std::rc::Rc::new(slint::VecModel::from(
                logs.iter()
                    .rev()
                    .take(20)
                    .map(|log| DnsLogEntry {
                        timestamp: log.timestamp.clone().into(),
                        domain: log.domain.clone().into(),
                        query_type: log.query_type.clone().into(),
                        response: log.response.clone().into(),
                        status: log.action.clone().into(),
                        latency: format!("{}ms", log.latency_ms).into(),
                    })
                    .collect::<Vec<_>>(),
            ));

            let all_logs = std::rc::Rc::new(slint::VecModel::from(
                logs.iter()
                    .rev()
                    .map(|log| DnsLogEntry {
                        timestamp: log.timestamp.clone().into(),
                        domain: log.domain.clone().into(),
                        query_type: log.query_type.clone().into(),
                        response: log.response.clone().into(),
                        status: log.action.clone().into(),
                        latency: format!("{}ms", log.latency_ms).into(),
                    })
                    .collect::<Vec<_>>(),
            ));

            let upstream_servers_model =
                std::rc::Rc::new(slint::VecModel::from(upstream_servers));

            if let Some(ui) = ui_weak.upgrade() {
                ui.set_recent_logs(recent_logs.into());
                ui.set_all_logs(all_logs.into());
                ui.set_upstream_servers(upstream_servers_model.into());
            }
        }
    });

    // 在主线程中处理 UI 更新
    let ui_handle = ui.as_weak();
    let mut ui_receiver = ui_receiver;
    let timer = Timer::default();
    timer.start(
        slint::TimerMode::Repeated,
        std::time::Duration::from_millis(100),
        move || {
            if let Ok(ui_state) = ui_receiver.try_recv() {
                if let Some(ui) = ui_handle.upgrade() {
                    ui.set_dns_running(ui_state.dns_running);
                    ui.set_tun_running(ui_state.tun_running);
                    ui.set_total_queries(ui_state.total_queries);
                    ui.set_blocked_queries(ui_state.blocked_queries);
                    ui.set_cached_queries(ui_state.cached_queries);
                    ui.set_avg_latency(ui_state.avg_latency);
                    ui.set_memory_usage(ui_state.memory_usage);
                    ui.set_total_rules(ui_state.total_rules);
                    ui.set_block_rules(ui_state.block_rules);
                    ui.set_allow_rules(ui_state.allow_rules);
                    ui.set_listen_port(ui_state.listen_port.into());
                    ui.set_auto_start(ui_state.auto_start);
                    ui.set_cache_size(ui_state.cache_size);
                    ui.set_cache_ttl(ui_state.cache_ttl);
                }
            }
        },
    );

    // 自动启动 DNS 服务
    if config.proxy.auto_start {
        let server = state.server.clone();
        tokio::spawn(async move {
            tokio::time::sleep(std::time::Duration::from_millis(500)).await;
            let mut server = server.lock().await;
            if let Err(e) = server.start().await {
                tracing::error!("自动启动DNS服务失败: {}", e);
            } else {
                tracing::info!("DNS服务已自动启动");
            }
        });
    }

    // 自动启动 TUN
    if config.tun.enabled {
        let tun_device = state.tun_device.clone();
        let tun_config = state.tun_config.clone();
        let server = state.server.clone();
        tokio::spawn(async move {
            tokio::time::sleep(std::time::Duration::from_secs(2)).await;
            let config = tun_config.lock().await.clone();
            let mut tun = tun_device.lock().await;
            *tun = TunDevice::new(config);
            match tun.start().await {
                Ok(()) => {
                    tracing::info!("TUN已自动启动");
                    let tun_clone = tun_device.clone();
                    drop(tun);
                    let server = server.lock().await;
                    let handler = server.get_dns_handler();
                    let interceptor = DnsInterceptor::new(tun_clone);
                    interceptor.start(handler).await;
                }
                Err(e) => {
                    tracing::error!("自动启动TUN失败: {}", e);
                }
            }
        });
    }

    ui.run()?;
    Ok(())
}

fn setup_callbacks(ui: &MainWindow, state: Arc<AppState>) {
    // 启动 DNS
    let state_dns = state.clone();
    ui.on_start_dns(move || {
        let server = state_dns.server.clone();
        tokio::spawn(async move {
            let mut server = server.lock().await;
            if let Err(e) = server.start().await {
                tracing::error!("启动DNS服务失败: {}", e);
            }
        });
    });

    // 停止 DNS
    let state_dns = state.clone();
    ui.on_stop_dns(move || {
        let server = state_dns.server.clone();
        tokio::spawn(async move {
            let mut server = server.lock().await;
            server.stop().await;
        });
    });

    // 启动 TUN
    let state_tun = state.clone();
    ui.on_start_tun(move || {
        let tun_device = state_tun.tun_device.clone();
        let tun_config = state_tun.tun_config.clone();
        let server = state_tun.server.clone();
        tokio::spawn(async move {
            let config = tun_config.lock().await.clone();
            let mut tun = tun_device.lock().await;
            *tun = TunDevice::new(config);
            match tun.start().await {
                Ok(()) => {
                    tracing::info!("TUN已启动");
                    let tun_clone = tun_device.clone();
                    drop(tun);
                    let server = server.lock().await;
                    let handler = server.get_dns_handler();
                    let interceptor = DnsInterceptor::new(tun_clone);
                    interceptor.start(handler).await;
                }
                Err(e) => {
                    tracing::error!("启动TUN失败: {}", e);
                }
            }
        });
    });

    // 停止 TUN
    let state_tun = state.clone();
    ui.on_stop_tun(move || {
        let tun_device = state_tun.tun_device.clone();
        tokio::spawn(async move {
            let mut tun = tun_device.lock().await;
            tun.stop().await;
        });
    });

    // 保存 DNS 设置
    let state_save = state.clone();
    ui.on_save_dns_settings(move |port, auto_start, cache_size, cache_ttl| {
        let config = state_save.config.clone();
        let server = state_save.server.clone();
        tokio::spawn(async move {
            let mut cfg = config.lock().await;
            cfg.proxy.listen_port = port.to_string().parse().unwrap_or(53);
            cfg.proxy.auto_start = auto_start;
            cfg.proxy.cache_size = cache_size as usize;
            cfg.proxy.cache_ttl = cache_ttl as u64;
            let _ = cfg.save();
            drop(cfg);

            // 重启服务器
            let mut server = server.lock().await;
            if server.is_running().await {
                server.stop().await;
                tokio::time::sleep(std::time::Duration::from_millis(300)).await;
                let config = config.lock().await.clone();
                *server = DnsServer::new(config);
                let _ = server.start().await;
            }
        });
    });

    // 保存高级设置
    ui.on_save_advanced_settings(move || {
        // TODO: 从 UI 获取设置值并保存
    });

    // 清空日志
    let state_logs = state.clone();
    ui.on_clear_logs(move || {
        let server = state_logs.server.clone();
        tokio::spawn(async move {
            let server = server.lock().await;
            server.clear_logs();
        });
    });

    // 导出日志
    ui.on_export_logs(|| {
        // TODO: 实现日志导出
    });

    // 导入规则
    ui.on_import_rules(|| {
        // TODO: 实现规则导入
    });

    // 导出规则
    ui.on_export_rules(|| {
        // TODO: 实现规则导出
    });
}

