import { Button, VerticalBox, HorizontalBox, LineEdit, CheckBox, ScrollView, GroupBox, Switch } from "std-widgets.slint";

// 颜色主题 - 现代深色主题
global Theme {
    in-out property <color> bg-primary: #0f0f14;
    in-out property <color> bg-secondary: #16161e;
    in-out property <color> bg-card: #1e1e28;
    in-out property <color> bg-hover: #252530;
    in-out property <color> text-primary: #e8e8ed;
    in-out property <color> text-secondary: #8888a0;
    in-out property <color> text-muted: #555568;
    in-out property <color> accent: #7c5cfc;
    in-out property <color> accent-hover: #9070ff;
    in-out property <color> accent-glow: #7c5cfc40;
    in-out property <color> success: #00d68f;
    in-out property <color> success-bg: #00d68f15;
    in-out property <color> warning: #ffaa00;
    in-out property <color> warning-bg: #ffaa0015;
    in-out property <color> error: #ff4466;
    in-out property <color> error-bg: #ff446615;
    in-out property <color> border: #2a2a38;
    in-out property <color> border-light: #353545;
}

// DNS日志条目
struct DnsLogEntry {
    timestamp: string,
    domain: string,
    query-type: string,
    response: string,
    status: string,
    latency: string,
}

// 分隔线
component Divider inherits Rectangle {
    height: 1px;
    background: Theme.border;
}

// 状态指示器（带脉冲动画）
component StatusIndicator inherits Rectangle {
    in property <bool> active: false;
    width: 10px;
    height: 10px;
    border-radius: 5px;
    background: active ? Theme.success : Theme.error;

    if active: Rectangle {
        width: 10px;
        height: 10px;
        border-radius: 5px;
        background: Theme.success;
        opacity: 0.4;
        // 脉冲效果可以通过动画实现
    }
}

// 侧边栏组件
component SideBar inherits Rectangle {
    in-out property <int> current-page: 0;
    callback page-changed(int);

    width: 220px;
    background: Theme.bg-secondary;
    border-right-width: 1px;
    border-right-color: Theme.border;

    VerticalLayout {
        padding: 0px;

        // Logo区域
        Rectangle {
            height: 80px;
            background: Theme.bg-primary;

            VerticalLayout {
                alignment: center;
                spacing: 4px;

                Text {
                    text: "⚡ DNS Proxy";
                    font-size: 22px;
                    font-weight: 800;
                    color: Theme.text-primary;
                    horizontal-alignment: center;
                    letter-spacing: 1px;
                }

                Text {
                    text: "v1.0.0 • Slint Edition";
                    font-size: 11px;
                    color: Theme.text-muted;
                    horizontal-alignment: center;
                }
            }
        }

        Divider {}

        Rectangle { height: 16px; }

        // 菜单项
        for page[index] in [
            { icon: "📊", label: "仪表盘", desc: "实时监控" },
            { icon: "⚙️", label: "DNS 设置", desc: "服务器配置" },
            { icon: "📋", label: "规则管理", desc: "黑白名单" },
            { icon: "📡", label: "查询日志", desc: "请求记录" },
            { icon: "🔧", label: "高级设置", desc: "TUN/DoH" },
        ]: Rectangle {
            height: 52px;
            margin-left: 12px;
            margin-right: 12px;
            background: current-page == index ? Theme.accent : transparent;
            border-radius: 10px;
            border-width: current-page == index ? 0px : 0px;

            states [
                hovered when touch.has-hover: {
                    background: current-page == index ? Theme.accent : Theme.bg-hover;
                }
            ]

            touch := TouchArea {
                clicked => {
                    current-page = index;
                    page-changed(index);
                }
            }

            HorizontalLayout {
                spacing: 12px;
                padding-left: 16px;
                alignment: start;

                Rectangle {
                    width: 24px;
                    height: 24px;
                    vertical-alignment: center;

                    Text {
                        text: page.icon;
                        font-size: 18px;
                        horizontal-alignment: center;
                        vertical-alignment: center;
                    }
                }

                VerticalLayout {
                    alignment: center;
                    spacing: 2px;

                    Text {
                        text: page.label;
                        font-size: 14px;
                        font-weight: current-page == index ? 600 : 400;
                        color: current-page == index ? white : Theme.text-primary;
                    }

                    Text {
                        text: page.desc;
                        font-size: 11px;
                        color: current-page == index ? #ffffff80 : Theme.text-muted;
                    }
                }
            }
        }

        Rectangle { vertical-stretch: 1; }

        // 底部状态
        Rectangle {
            height: 60px;
            background: Theme.bg-primary;
            border-top-width: 1px;
            border-top-color: Theme.border;

            HorizontalLayout {
                alignment: center;
                spacing: 8px;
                padding: 16px;

                Rectangle {
                    width: 8px;
                    height: 8px;
                    border-radius: 4px;
                    background: Theme.success;
                    vertical-alignment: center;
                }

                Text {
                    text: "服务运行中";
                    font-size: 12px;
                    color: Theme.text-secondary;
                    vertical-alignment: center;
                }
            }
        }
    }
}

// 统计卡片 - 现代设计
component StatCard inherits Rectangle {
    in property <string> title;
    in property <string> value;
    in property <string> icon;
    in property <color> icon-color: Theme.accent;
    in property <color> value-color: Theme.text-primary;

    background: Theme.bg-card;
    border-radius: 16px;
    border-width: 1px;
    border-color: Theme.border;
    min-height: 120px;

    // 悬停效果
    states [
        hovered when touch.has-hover: {
            background: Theme.bg-hover;
            border-color: Theme.border-light;
        }
    ]

    touch := TouchArea {}

    VerticalLayout {
        padding: 20px;
        spacing: 12px;

        HorizontalLayout {
            spacing: 10px;

            Rectangle {
                width: 36px;
                height: 36px;
                border-radius: 10px;
                background: icon-color + "15";
                vertical-alignment: center;

                Text {
                    text: icon;
                    font-size: 18px;
                    horizontal-alignment: center;
                    vertical-alignment: center;
                }
            }

            Text {
                text: title;
                font-size: 13px;
                color: Theme.text-secondary;
                vertical-alignment: center;
            }
        }

        Text {
            text: value;
            font-size: 32px;
            font-weight: 700;
            color: value-color;
        }
    }
}

// 状态卡片（带开关）
component StatusCard inherits Rectangle {
    in property <string> title;
    in property <string> subtitle;
    in property <bool> active: false;
    in property <string> icon;
    callback toggle();

    background: Theme.bg-card;
    border-radius: 16px;
    border-width: 1px;
    border-color: active ? Theme.success + "40" : Theme.border;
    min-height: 100px;

    HorizontalLayout {
        padding: 20px;
        spacing: 16px;

        Rectangle {
            width: 48px;
            height: 48px;
            border-radius: 12px;
            background: active ? Theme.success-bg : Theme.error-bg;
            vertical-alignment: center;

            Text {
                text: icon;
                font-size: 24px;
                horizontal-alignment: center;
                vertical-alignment: center;
            }
        }

        VerticalLayout {
            alignment: center;
            spacing: 4px;
            horizontal-stretch: 1;

            Text {
                text: title;
                font-size: 16px;
                font-weight: 600;
                color: Theme.text-primary;
            }

            Text {
                text: subtitle;
                font-size: 13px;
                color: active ? Theme.success : Theme.text-secondary;
            }
        }

        Switch {
            checked: active;
            toggled => {
                toggle();
            }
        }
    }
}

// 仪表盘页面
component DashboardPage inherits ScrollView {
    in property <int> total-queries: 0;
    in property <int> blocked-queries: 0;
    in property <int> cached-queries: 0;
    in property <float> avg-latency: 0;
    in property <bool> dns-running: false;
    in property <bool> tun-running: false;
    in property <int> memory-usage: 0;
    in property <[DnsLogEntry]> recent-logs;

    callback start-dns();
    callback stop-dns();
    callback start-tun();
    callback stop-tun();

    VerticalLayout {
        padding: 24px;
        spacing: 20px;

        // 标题
        Text {
            text: "仪表盘";
            font-size: 28px;
            font-weight: 700;
            color: Theme.text-primary;
        }

        // 状态卡片
        HorizontalLayout {
            spacing: 16px;

            StatusCard {
                title: "DNS 服务";
                subtitle: dns-running ? "运行中 - 监听端口 53" : "已停止";
                active: dns-running;
                icon: "🌐";
                horizontal-stretch: 1;
                toggle => {
                    if dns-running {
                        stop-dns();
                    } else {
                        start-dns();
                    }
                }
            }

            StatusCard {
                title: "TUN 模式";
                subtitle: tun-running ? "运行中 - 全局代理" : "已停止";
                active: tun-running;
                icon: "🔒";
                horizontal-stretch: 1;
                toggle => {
                    if tun-running {
                        stop-tun();
                    } else {
                        start-tun();
                    }
                }
            }
        }

        // 统计卡片
        HorizontalLayout {
            spacing: 16px;

            StatCard {
                title: "总查询";
                value: total-queries;
                icon: "📊";
                icon-color: Theme.accent;
                horizontal-stretch: 1;
            }

            StatCard {
                title: "已阻止";
                value: blocked-queries;
                icon: "🛡️";
                icon-color: Theme.error;
                value-color: Theme.error;
                horizontal-stretch: 1;
            }

            StatCard {
                title: "缓存命中";
                value: cached-queries;
                icon: "⚡";
                icon-color: Theme.success;
                value-color: Theme.success;
                horizontal-stretch: 1;
            }

            StatCard {
                title: "平均延迟";
                value: avg-latency + "ms";
                icon: "⏱️";
                icon-color: Theme.warning;
                horizontal-stretch: 1;
            }
        }

        // 最近日志
        Rectangle {
            background: Theme.bg-card;
            border-radius: 16px;
            border-width: 1px;
            border-color: Theme.border;
            min-height: 300px;

            VerticalLayout {
                padding: 20px;
                spacing: 16px;

                HorizontalLayout {
                    Text {
                        text: "最近查询";
                        font-size: 16px;
                        font-weight: 600;
                        color: Theme.text-primary;
                        vertical-alignment: center;
                    }

                    Rectangle { horizontal-stretch: 1; }

                    Text {
                        text: "共 " + recent-logs.length + " 条";
                        font-size: 13px;
                        color: Theme.text-muted;
                        vertical-alignment: center;
                    }
                }

                Divider {}

                for log in recent-logs: Rectangle {
                    height: 40px;
                    border-radius: 8px;
                    background: touch.has-hover ? Theme.bg-hover : transparent;

                    touch := TouchArea {}

                    HorizontalLayout {
                        spacing: 16px;
                        padding-left: 12px;
                        padding-right: 12px;

                        Text {
                            text: log.timestamp;
                            font-size: 12px;
                            color: Theme.text-muted;
                            width: 80px;
                            vertical-alignment: center;
                        }

                        Text {
                            text: log.domain;
                            font-size: 13px;
                            color: Theme.text-primary;
                            horizontal-stretch: 1;
                            overflow: elide;
                            vertical-alignment: center;
                        }

                        Rectangle {
                            width: 60px;
                            height: 24px;
                            border-radius: 6px;
                            background: log.status == "已阻止" ? Theme.error-bg : Theme.success-bg;
                            vertical-alignment: center;

                            Text {
                                text: log.status;
                                font-size: 11px;
                                font-weight: 500;
                                color: log.status == "已阻止" ? Theme.error : Theme.success;
                                horizontal-alignment: center;
                                vertical-alignment: center;
                            }
                        }

                        Text {
                            text: log.latency;
                            font-size: 12px;
                            color: Theme.text-muted;
                            width: 60px;
                            horizontal-alignment: right;
                            vertical-alignment: center;
                        }
                    }
                }
            }
        }
    }
}

// DNS设置页面
component DnsSettingsPage inherits ScrollView {
    in property <string> listen-port: "53";
    in property <bool> auto-start: true;
    in property <int> cache-size: 5000;
    in property <int> cache-ttl: 1800;
    in property <[string]> upstream-servers;

    callback save-settings(string, bool, int, int);

    VerticalLayout {
        padding: 24px;
        spacing: 20px;

        Text {
            text: "DNS 设置";
            font-size: 28px;
            font-weight: 700;
            color: Theme.text-primary;
        }

        // 监听配置
        Rectangle {
            background: Theme.bg-card;
            border-radius: 16px;
            border-width: 1px;
            border-color: Theme.border;

            VerticalLayout {
                padding: 24px;
                spacing: 20px;

                Text {
                    text: "🌐 监听配置";
                    font-size: 18px;
                    font-weight: 600;
                    color: Theme.text-primary;
                }

                Divider {}

                HorizontalLayout {
                    spacing: 16px;

                    VerticalLayout {
                        spacing: 8px;
                        horizontal-stretch: 1;

                        Text {
                            text: "监听端口";
                            font-size: 13px;
                            color: Theme.text-secondary;
                        }

                        LineEdit {
                            text: listen-port;
                            height: 44px;
                        }
                    }

                    VerticalLayout {
                        spacing: 8px;

                        Text {
                            text: "自动启动";
                            font-size: 13px;
                            color: Theme.text-secondary;
                        }

                        Switch {
                            checked: auto-start;
                        }
                    }
                }
            }
        }

        // 缓存配置
        Rectangle {
            background: Theme.bg-card;
            border-radius: 16px;
            border-width: 1px;
            border-color: Theme.border;

            VerticalLayout {
                padding: 24px;
                spacing: 20px;

                Text {
                    text: "⚡ 缓存配置";
                    font-size: 18px;
                    font-weight: 600;
                    color: Theme.text-primary;
                }

                Divider {}

                HorizontalLayout {
                    spacing: 16px;

                    VerticalLayout {
                        spacing: 8px;
                        horizontal-stretch: 1;

                        Text {
                            text: "缓存大小";
                            font-size: 13px;
                            color: Theme.text-secondary;
                        }

                        LineEdit {
                            text: cache-size;
                            height: 44px;
                        }
                    }

                    VerticalLayout {
                        spacing: 8px;
                        horizontal-stretch: 1;

                        Text {
                            text: "缓存 TTL (秒)";
                            font-size: 13px;
                            color: Theme.text-secondary;
                        }

                        LineEdit {
                            text: cache-ttl;
                            height: 44px;
                        }
                    }
                }
            }
        }

        // 上游服务器
        Rectangle {
            background: Theme.bg-card;
            border-radius: 16px;
            border-width: 1px;
            border-color: Theme.border;

            VerticalLayout {
                padding: 24px;
                spacing: 16px;

                HorizontalLayout {
                    Text {
                        text: "🌍 上游 DNS 服务器";
                        font-size: 18px;
                        font-weight: 600;
                        color: Theme.text-primary;
                        vertical-alignment: center;
                    }

                    Rectangle { horizontal-stretch: 1; }

                    Button {
                        text: "+ 添加服务器";
                        width: 120px;
                    }
                }

                Divider {}

                for server in upstream-servers: Rectangle {
                    height: 52px;
                    border-radius: 10px;
                    background: Theme.bg-hover;
                    border-width: 1px;
                    border-color: Theme.border;

                    HorizontalLayout {
                        padding-left: 16px;
                        padding-right: 16px;

                        Text {
                            text: server;
                            font-size: 14px;
                            color: Theme.text-primary;
                            vertical-alignment: center;
                            horizontal-stretch: 1;
                        }

                        Button {
                            text: "删除";
                            width: 70px;
                        }
                    }
                }
            }
        }

        // 保存按钮
        HorizontalLayout {
            alignment: end;

            Button {
                text: "保存设置";
                width: 140px;
                height: 44px;
                clicked => {
                    save-settings(listen-port, auto-start, cache-size, cache-ttl);
                }
            }
        }
    }
}

// 规则管理页面
component RulesPage inherits ScrollView {
    in property <int> total-rules: 0;
    in property <int> block-rules: 0;
    in property <int> allow-rules: 0;
    in property <[string]> rule-list;

    callback import-rules();
    callback export-rules();

    VerticalLayout {
        padding: 24px;
        spacing: 20px;

        HorizontalLayout {
            Text {
                text: "规则管理";
                font-size: 28px;
                font-weight: 700;
                color: Theme.text-primary;
                vertical-alignment: center;
            }

            Rectangle { horizontal-stretch: 1; }

            Button {
                text: "导入规则";
                width: 100px;
            }

            Button {
                text: "导出规则";
                width: 100px;
            }
        }

        // 规则统计
        HorizontalLayout {
            spacing: 16px;

            StatCard {
                title: "总规则数";
                value: total-rules;
                icon: "📋";
                icon-color: Theme.accent;
                horizontal-stretch: 1;
            }

            StatCard {
                title: "阻止规则";
                value: block-rules;
                icon: "🚫";
                icon-color: Theme.error;
                value-color: Theme.error;
                horizontal-stretch: 1;
            }

            StatCard {
                title: "允许规则";
                value: allow-rules;
                icon: "✅";
                icon-color: Theme.success;
                value-color: Theme.success;
                horizontal-stretch: 1;
            }
        }

        // 规则列表
        Rectangle {
            background: Theme.bg-card;
            border-radius: 16px;
            border-width: 1px;
            border-color: Theme.border;
            min-height: 400px;

            VerticalLayout {
                padding: 20px;
                spacing: 12px;

                Text {
                    text: "规则列表";
                    font-size: 16px;
                    font-weight: 600;
                    color: Theme.text-primary;
                }

                Divider {}

                for rule in rule-list: Rectangle {
                    height: 44px;
                    border-radius: 8px;
                    background: Theme.bg-hover;

                    HorizontalLayout {
                        padding-left: 16px;
                        padding-right: 16px;

                        Text {
                            text: rule;
                            font-size: 13px;
                            color: Theme.text-primary;
                            vertical-alignment: center;
                            horizontal-stretch: 1;
                            overflow: elide;
                        }

                        Button {
                            text: "删除";
                            width: 70px;
                        }
                    }
                }
            }
        }
    }
}

// 日志页面
component LogsPage inherits ScrollView {
    in property <[DnsLogEntry]> logs;
    in property <bool> auto-scroll: true;

    callback clear-logs();
    callback export-logs();

    VerticalLayout {
        padding: 24px;
        spacing: 20px;

        HorizontalLayout {
            Text {
                text: "查询日志";
                font-size: 28px;
                font-weight: 700;
                color: Theme.text-primary;
                vertical-alignment: center;
            }

            Rectangle { horizontal-stretch: 1; }

            Button {
                text: "清空日志";
                width: 100px;
            }

            Button {
                text: "导出日志";
                width: 100px;
            }
        }

        // 日志表格
        Rectangle {
            background: Theme.bg-card;
            border-radius: 16px;
            border-width: 1px;
            border-color: Theme.border;
            min-height: 500px;

            VerticalLayout {
                padding: 20px;
                spacing: 12px;

                // 表头
                Rectangle {
                    height: 40px;
                    background: Theme.bg-hover;
                    border-radius: 8px;

                    HorizontalLayout {
                        padding-left: 16px;
                        padding-right: 16px;
                        spacing: 16px;

                        Text {
                            text: "时间";
                            font-size: 12px;
                            font-weight: 600;
                            color: Theme.text-secondary;
                            width: 80px;
                            vertical-alignment: center;
                        }

                        Text {
                            text: "域名";
                            font-size: 12px;
                            font-weight: 600;
                            color: Theme.text-secondary;
                            horizontal-stretch: 1;
                            vertical-alignment: center;
                        }

                        Text {
                            text: "类型";
                            font-size: 12px;
                            font-weight: 600;
                            color: Theme.text-secondary;
                            width: 50px;
                            vertical-alignment: center;
                        }

                        Text {
                            text: "状态";
                            font-size: 12px;
                            font-weight: 600;
                            color: Theme.text-secondary;
                            width: 70px;
                            horizontal-alignment: center;
                            vertical-alignment: center;
                        }

                        Text {
                            text: "延迟";
                            font-size: 12px;
                            font-weight: 600;
                            color: Theme.text-secondary;
                            width: 70px;
                            horizontal-alignment: right;
                            vertical-alignment: center;
                        }
                    }
                }

                // 日志行
                for log in logs: Rectangle {
                    height: 40px;
                    border-radius: 8px;
                    background: touch.has-hover ? Theme.bg-hover : transparent;

                    touch := TouchArea {}

                    HorizontalLayout {
                        padding-left: 16px;
                        padding-right: 16px;
                        spacing: 16px;

                        Text {
                            text: log.timestamp;
                            font-size: 12px;
                            color: Theme.text-muted;
                            width: 80px;
                            vertical-alignment: center;
                        }

                        Text {
                            text: log.domain;
                            font-size: 13px;
                            color: Theme.text-primary;
                            horizontal-stretch: 1;
                            overflow: elide;
                            vertical-alignment: center;
                        }

                        Text {
                            text: log.query-type;
                            font-size: 12px;
                            color: Theme.text-secondary;
                            width: 50px;
                            vertical-alignment: center;
                        }

                        Rectangle {
                            width: 70px;
                            height: 24px;
                            border-radius: 6px;
                            background: log.status == "已阻止" ? Theme.error-bg : Theme.success-bg;
                            vertical-alignment: center;

                            Text {
                                text: log.status;
                                font-size: 11px;
                                font-weight: 500;
                                color: log.status == "已阻止" ? Theme.error : Theme.success;
                                horizontal-alignment: center;
                                vertical-alignment: center;
                            }
                        }

                        Text {
                            text: log.latency;
                            font-size: 12px;
                            color: Theme.text-muted;
                            width: 70px;
                            horizontal-alignment: right;
                            vertical-alignment: center;
                        }
                    }
                }
            }
        }
    }
}

// 高级设置页面
component AdvancedSettingsPage inherits ScrollView {
    in property <bool> enable-tun: false;
    in property <string> tun-interface: "dns-proxy-tun";
    in property <string> tun-gateway: "10.0.0.1";
    in property <string> tun-dns: "10.0.0.1";
    in property <bool> enable-doh: false;
    in property <string> doh-url: "";
    in property <bool> enable-dot: false;

    callback save-advanced-settings();

    VerticalLayout {
        padding: 24px;
        spacing: 20px;

        Text {
            text: "高级设置";
            font-size: 28px;
            font-weight: 700;
            color: Theme.text-primary;
        }

        // TUN模式配置
        Rectangle {
            background: Theme.bg-card;
            border-radius: 16px;
            border-width: 1px;
            border-color: enable-tun ? Theme.accent + "40" : Theme.border;

            VerticalLayout {
                padding: 24px;
                spacing: 20px;

                HorizontalLayout {
                    Text {
                        text: "🔒 TUN 模式";
                        font-size: 18px;
                        font-weight: 600;
                        color: Theme.text-primary;
                        vertical-alignment: center;
                    }

                    Rectangle { horizontal-stretch: 1; }

                    Switch {
                        checked: enable-tun;
                    }
                }

                Text {
                    text: "TUN 模式可以全局代理所有 DNS 请求，包括系统级应用";
                    font-size: 13px;
                    color: Theme.text-secondary;
                }

                Divider {}

                if enable-tun: VerticalLayout {
                    spacing: 16px;

                    VerticalLayout {
                        spacing: 8px;

                        Text {
                            text: "接口名称";
                            font-size: 13px;
                            color: Theme.text-secondary;
                        }

                        LineEdit {
                            text: tun-interface;
                            height: 44px;
                        }
                    }

                    VerticalLayout {
                        spacing: 8px;

                        Text {
                            text: "网关地址";
                            font-size: 13px;
                            color: Theme.text-secondary;
                        }

                        LineEdit {
                            text: tun-gateway;
                            height: 44px;
                        }
                    }

                    VerticalLayout {
                        spacing: 8px;

                        Text {
                            text: "DNS 地址";
                            font-size: 13px;
                            color: Theme.text-secondary;
                        }

                        LineEdit {
                            text: tun-dns;
                            height: 44px;
                        }
                    }
                }
            }
        }

        // DoH/DoT配置
        Rectangle {
            background: Theme.bg-card;
            border-radius: 16px;
            border-width: 1px;
            border-color: enable-doh || enable-dot ? Theme.accent + "40" : Theme.border;

            VerticalLayout {
                padding: 24px;
                spacing: 20px;

                Text {
                    text: "🔐 加密 DNS";
                    font-size: 18px;
                    font-weight: 600;
                    color: Theme.text-primary;
                }

                Text {
                    text: "使用加密协议保护 DNS 查询隐私";
                    font-size: 13px;
                    color: Theme.text-secondary;
                }

                Divider {}

                // DoH
                Rectangle {
                    height: 60px;
                    border-radius: 10px;
                    background: Theme.bg-hover;

                    HorizontalLayout {
                        padding-left: 16px;
                        padding-right: 16px;

                        VerticalLayout {
                            alignment: center;

                            Text {
                                text: "DNS-over-HTTPS (DoH)";
                                font-size: 14px;
                                font-weight: 500;
                                color: Theme.text-primary;
                            }

                            Text {
                                text: "通过 HTTPS 加密 DNS 查询";
                                font-size: 12px;
                                color: Theme.text-secondary;
                            }
                        }

                        Rectangle { horizontal-stretch: 1; }

                        Switch {
                            checked: enable-doh;
                            vertical-alignment: center;
                        }
                    }
                }

                if enable-doh: LineEdit {
                    text: doh-url;
                    height: 44px;
                    placeholder-text: "https://cloudflare-dns.com/dns-query";
                }

                // DoT
                Rectangle {
                    height: 60px;
                    border-radius: 10px;
                    background: Theme.bg-hover;

                    HorizontalLayout {
                        padding-left: 16px;
                        padding-right: 16px;

                        VerticalLayout {
                            alignment: center;

                            Text {
                                text: "DNS-over-TLS (DoT)";
                                font-size: 14px;
                                font-weight: 500;
                                color: Theme.text-primary;
                            }

                            Text {
                                text: "通过 TLS 加密 DNS 查询";
                                font-size: 12px;
                                color: Theme.text-secondary;
                            }
                        }

                        Rectangle { horizontal-stretch: 1; }

                        Switch {
                            checked: enable-dot;
                            vertical-alignment: center;
                        }
                    }
                }
            }
        }

        // 保存按钮
        HorizontalLayout {
            alignment: end;

            Button {
                text: "保存设置";
                width: 140px;
                height: 44px;
                clicked => {
                    save-advanced-settings();
                }
            }
        }
    }
}

// 主窗口
export component MainWindow inherits Window {
    title: "DNS Proxy";
    min-width: 1200px;
    min-height: 750px;
    background: Theme.bg-primary;
    icon: @image-url("../public/icon.ico");

    // 状态属性
    in-out property <int> current-page: 0;
    in-out property <bool> dns-running: false;
    in-out property <bool> tun-running: false;
    in-out property <int> total-queries: 0;
    in-out property <int> blocked-queries: 0;
    in-out property <int> cached-queries: 0;
    in-out property <float> avg-latency: 0;
    in-out property <int> memory-usage: 0;
    in-out property <int> total-rules: 0;
    in-out property <int> block-rules: 0;
    in-out property <int> allow-rules: 0;
    in-out property <string> listen-port: "53";
    in-out property <bool> auto-start: true;
    in-out property <int> cache-size: 5000;
    in-out property <int> cache-ttl: 1800;
    in-out property <bool> enable-tun: false;
    in-out property <string> tun-interface: "dns-proxy-tun";
    in-out property <string> tun-gateway: "10.0.0.1";

    // 数据
    in-out property <[DnsLogEntry]> recent-logs;
    in-out property <[DnsLogEntry]> all-logs;
    in-out property <[string]> upstream-servers;
    in-out property <[string]> rule-list;

    // 回调
    callback start-dns();
    callback stop-dns();
    callback start-tun();
    callback stop-tun();
    callback save-dns-settings(string, bool, int, int);
    callback save-advanced-settings();
    callback clear-logs();
    callback export-logs();
    callback import-rules();
    callback export-rules();

    HorizontalLayout {
        padding: 0px;

        // 侧边栏
        SideBar {
            current-page: current-page;
            page-changed(page) => {
                current-page = page;
            }
        }

        // 主内容区
        if current-page == 0: DashboardPage {
            total-queries: total-queries;
            blocked-queries: blocked-queries;
            cached-queries: cached-queries;
            avg-latency: avg-latency;
            dns-running: dns-running;
            tun-running: tun-running;
            memory-usage: memory-usage;
            recent-logs: recent-logs;
            start-dns => { start-dns(); }
            stop-dns => { stop-dns(); }
            start-tun => { start-tun(); }
            stop-tun => { stop-tun(); }
        }

        if current-page == 1: DnsSettingsPage {
            listen-port: listen-port;
            auto-start: auto-start;
            cache-size: cache-size;
            cache-ttl: cache-ttl;
            upstream-servers: upstream-servers;
            save-settings(port, auto, size, ttl) => {
                save-dns-settings(port, auto, size, ttl);
            }
        }

        if current-page == 2: RulesPage {
            total-rules: total-rules;
            block-rules: block-rules;
            allow-rules: allow-rules;
            rule-list: rule-list;
            import-rules => { import-rules(); }
            export-rules => { export-rules(); }
        }

        if current-page == 3: LogsPage {
            logs: all-logs;
            clear-logs => { clear-logs(); }
            export-logs => { export-logs(); }
        }

        if current-page == 4: AdvancedSettingsPage {
            enable-tun: enable-tun;
            tun-interface: tun-interface;
            tun-gateway: tun-gateway;
            save-advanced-settings => { save-advanced-settings(); }
        }
    }
}

toolUseResult.content:
import { Button, VerticalBox, HorizontalBox, LineEdit, CheckBox, ScrollView, GroupBox, Switch } from "std-widgets.slint";

// 颜色主题 - 现代深色主题
global Theme {
    in-out property <color> bg-primary: #0f0f14;
    in-out property <color> bg-secondary: #16161e;
    in-out property <color> bg-card: #1e1e28;
    in-out property <color> bg-hover: #252530;
    in-out property <color> text-primary: #e8e8ed;
    in-out property <color> text-secondary: #8888a0;
    in-out property <color> text-muted: #555568;
    in-out property <color> accent: #7c5cfc;
    in-out property <color> accent-hover: #9070ff;
    in-out property <color> accent-glow: #7c5cfc40;
    in-out property <color> success: #00d68f;
    in-out property <color> success-bg: #00d68f15;
    in-out property <color> warning: #ffaa00;
    in-out property <color> warning-bg: #ffaa0015;
    in-out property <color> error: #ff4466;
    in-out property <color> error-bg: #ff446615;
    in-out property <color> border: #2a2a38;
    in-out property <color> border-light: #353545;
}

// DNS日志条目
struct DnsLogEntry {
    timestamp: string,
    domain: string,
    query-type: string,
    response: string,
    status: string,
    latency: string,
}

// 分隔线
component Divider inherits Rectangle {
    height: 1px;
    background: Theme.border;
}

// 状态指示器（带脉冲动画）
component StatusIndicator inherits Rectangle {
    in property <bool> active: false;
    width: 10px;
    height: 10px;
    border-radius: 5px;
    background: active ? Theme.success : Theme.error;

    if active: Rectangle {
        width: 10px;
        height: 10px;
        border-radius: 5px;
        background: Theme.success;
        opacity: 0.4;
        // 脉冲效果可以通过动画实现
    }
}

// 侧边栏组件
component SideBar inherits Rectangle {
    in-out property <int> current-page: 0;
    callback page-changed(int);

    width: 220px;
    background: Theme.bg-secondary;
    border-right-width: 1px;
    border-right-color: Theme.border;

    VerticalLayout {
        padding: 0px;

        // Logo区域
        Rectangle {
            height: 80px;
            background: Theme.bg-primary;

            VerticalLayout {
                alignment: center;
                spacing: 4px;

                Text {
                    text: "⚡ DNS Proxy";
                    font-size: 22px;
                    font-weight: 800;
                    color: Theme.text-primary;
                    horizontal-alignment: center;
                    letter-spacing: 1px;
                }

                Text {
                    text: "v1.0.0 • Slint Edition";
                    font-size: 11px;
                    color: Theme.text-muted;
                    horizontal-alignment: center;
                }
            }
        }

        Divider {}

        Rectangle { height: 16px; }

        // 菜单项
        for page[index] in [
            { icon: "📊", label: "仪表盘", desc: "实时监控" },
            { icon: "⚙️", label: "DNS 设置", desc: "服务器配置" },
            { icon: "📋", label: "规则管理", desc: "黑白名单" },
            { icon: "📡", label: "查询日志", desc: "请求记录" },
            { icon: "🔧", label: "高级设置", desc: "TUN/DoH" },
        ]: Rectangle {
            height: 52px;
            margin-left: 12px;
            margin-right: 12px;
            background: current-page == index ? Theme.accent : transparent;
            border-radius: 10px;
            border-width: current-page == index ? 0px : 0px;

            states [
                hovered when touch.has-hover: {
                    background: current-page == index ? Theme.accent : Theme.bg-hover;
                }
            ]

            touch := TouchArea {
                clicked => {
                    current-page = index;
                    page-changed(index);
                }
            }

            HorizontalLayout {
                spacing: 12px;
                padding-left: 16px;
                alignment: start;

                Rectangle {
                    width: 24px;
                    height: 24px;
                    vertical-alignment: center;

                    Text {
                        text: page.icon;
                        font-size: 18px;
                        horizontal-alignment: center;
                        vertical-alignment: center;
                    }
                }

                VerticalLayout {
                    alignment: center;
                    spacing: 2px;

                    Text {
                        text: page.label;
                        font-size: 14px;
                        font-weight: current-page == index ? 600 : 400;
                        color: current-page == index ? white : Theme.text-primary;
                    }

                    Text {
                        text: page.desc;
                        font-size: 11px;
                        color: current-page == index ? #ffffff80 : Theme.text-muted;
                    }
                }
            }
        }

        Rectangle { vertical-stretch: 1; }

        // 底部状态
        Rectangle {
            height: 60px;
            background: Theme.bg-primary;
            border-top-width: 1px;
            border-top-color: Theme.border;

            HorizontalLayout {
                alignment: center;
                spacing: 8px;
                padding: 16px;

                Rectangle {
                    width: 8px;
                    height: 8px;
                    border-radius: 4px;
                    background: Theme.success;
                    vertical-alignment: center;
                }

                Text {
                    text: "服务运行中";
                    font-size: 12px;
                    color: Theme.text-secondary;
                    vertical-alignment: center;
                }
            }
        }
    }
}

// 统计卡片 - 现代设计
component StatCard inherits Rectangle {
    in property <string> title;
    in property <string> value;
    in property <string> icon;
    in property <color> icon-color: Theme.accent;
    in property <color> value-color: Theme.text-primary;

    background: Theme.bg-card;
    border-radius: 16px;
    border-width: 1px;
    border-color: Theme.border;
    min-height: 120px;

    // 悬停效果
    states [
        hovered when touch.has-hover: {
            background: Theme.bg-hover;
            border-color: Theme.border-light;
        }
    ]

    touch := TouchArea {}

    VerticalLayout {
        padding: 20px;
        spacing: 12px;

        HorizontalLayout {
            spacing: 10px;

            Rectangle {
                width: 36px;
                height: 36px;
                border-radius: 10px;
                background: icon-color + "15";
                vertical-alignment: center;

                Text {
                    text: icon;
                    font-size: 18px;
                    horizontal-alignment: center;
                    vertical-alignment: center;
                }
            }

            Text {
                text: title;
                font-size: 13px;
                color: Theme.text-secondary;
                vertical-alignment: center;
            }
        }

        Text {
            text: value;
            font-size: 32px;
            font-weight: 700;
            color: value-color;
        }
    }
}

// 状态卡片（带开关）
component StatusCard inherits Rectangle {
    in property <string> title;
    in property <string> subtitle;
    in property <bool> active: false;
    in property <string> icon;
    callback toggle();

    background: Theme.bg-card;
    border-radius: 16px;
    border-width: 1px;
    border-color: active ? Theme.success + "40" : Theme.border;
    min-height: 100px;

    HorizontalLayout {
        padding: 20px;
        spacing: 16px;

        Rectangle {
            width: 48px;
            height: 48px;
            border-radius: 12px;
            background: active ? Theme.success-bg : Theme.error-bg;
            vertical-alignment: center;

            Text {
                text: icon;
                font-size: 24px;
                horizontal-alignment: center;
                vertical-alignment: center;
            }
        }

        VerticalLayout {
            alignment: center;
            spacing: 4px;
            horizontal-stretch: 1;

            Text {
                text: title;
                font-size: 16px;
                font-weight: 600;
                color: Theme.text-primary;
            }

            Text {
                text: subtitle;
                font-size: 13px;
                color: active ? Theme.success : Theme.text-secondary;
            }
        }

        Switch {
            checked: active;
            toggled => {
                toggle();
            }
        }
    }
}

// 仪表盘页面
component DashboardPage inherits ScrollView {
    in property <int> total-queries: 0;
    in property <int> blocked-queries: 0;
    in property <int> cached-queries: 0;
    in property <float> avg-latency: 0;
    in property <bool> dns-running: false;
    in property <bool> tun-running: false;
    in property <int> memory-usage: 0;
    in property <[DnsLogEntry]> recent-logs;

    callback start-dns();
    callback stop-dns();
    callback start-tun();
    callback stop-tun();

    VerticalLayout {
        padding: 24px;
        spacing: 20px;

        // 标题
        Text {
            text: "仪表盘";
            font-size: 28px;
            font-weight: 700;
            color: Theme.text-primary;
        }

        // 状态卡片
        HorizontalLayout {
            spacing: 16px;

            StatusCard {
                title: "DNS 服务";
                subtitle: dns-running ? "运行中 - 监听端口 53" : "已停止";
                active: dns-running;
                icon: "🌐";
                horizontal-stretch: 1;
                toggle => {
                    if dns-running {
                        stop-dns();
                    } else {
                        start-dns();
                    }
                }
            }

            StatusCard {
                title: "TUN 模式";
                subtitle: tun-running ? "运行中 - 全局代理" : "已停止";
                active: tun-running;
                icon: "🔒";
                horizontal-stretch: 1;
                toggle => {
                    if tun-running {
                        stop-tun();
                    } else {
                        start-tun();
                    }
                }
            }
        }

        // 统计卡片
        HorizontalLayout {
            spacing: 16px;

            StatCard {
                title: "总查询";
                value: total-queries;
                icon: "📊";
                icon-color: Theme.accent;
                horizontal-stretch: 1;
            }

            StatCard {
                title: "已阻止";
                value: blocked-queries;
                icon: "🛡️";
                icon-color: Theme.error;
                value-color: Theme.error;
                horizontal-stretch: 1;
            }

            StatCard {
                title: "缓存命中";
                value: cached-queries;
                icon: "⚡";
                icon-color: Theme.success;
                value-color: Theme.success;
                horizontal-stretch: 1;
            }

            StatCard {
                title: "平均延迟";
                value: avg-latency + "ms";
                icon: "⏱️";
                icon-color: Theme.warning;
                horizontal-stretch: 1;
            }
        }

        // 最近日志
        Rectangle {
            background: Theme.bg-card;
            border-radius: 16px;
            border-width: 1px;
            border-color: Theme.border;
            min-height: 300px;

            VerticalLayout {
                padding: 20px;
                spacing: 16px;

                HorizontalLayout {
                    Text {
                        text: "最近查询";
                        font-size: 16px;
                        font-weight: 600;
                        color: Theme.text-primary;
                        vertical-alignment: center;
                    }

                    Rectangle { horizontal-stretch: 1; }

                    Text {
                        text: "共 " + recent-logs.length + " 条";
                        font-size: 13px;
                        color: Theme.text-muted;
                        vertical-alignment: center;
                    }
                }

                Divider {}

                for log in recent-logs: Rectangle {
                    height: 40px;
                    border-radius: 8px;
                    background: touch.has-hover ? Theme.bg-hover : transparent;

                    touch := TouchArea {}

                    HorizontalLayout {
                        spacing: 16px;
                        padding-left: 12px;
                        padding-right: 12px;

                        Text {
                            text: log.timestamp;
                            font-size: 12px;
                            color: Theme.text-muted;
                            width: 80px;
                            vertical-alignment: center;
                        }

                        Text {
                            text: log.domain;
                            font-size: 13px;
