export component MainWindow inherits Window {
    title: "DNS Proxy";
    min-width: 1200px;
    min-height: 750px;
    background: Theme.bg-primary;
    icon: @image-url("../public/icon.ico");

    // 状态属性
    in-out property <int> current-page: 0;
    in-out property <bool> dns-running: false;
    in-out property <bool> tun-running: false;
    in-out property <int> total-queries: 0;
    in-out property <int> blocked-queries: 0;
    in-out property <int> cached-queries: 0;
    in-out property <float> avg-latency: 0;
    in-out property <int> memory-usage: 0;
    in-out property <int> total-rules: 0;
    in-out property <int> block-rules: 0;
    in-out property <int> allow-rules: 0;
    in-out property <string> listen-port: "53";
    in-out property <bool> auto-start: true;
    in-out property <int> cache-size: 5000;
    in-out property <int> cache-ttl: 1800;
    in-out property <bool> enable-tun: false;
    in-out property <string> tun-interface: "dns-proxy-tun";
    in-out property <string> tun-gateway: "10.0.0.1";

    // 数据
    in-out property <[DnsLogEntry]> recent-logs;
    in-out property <[DnsLogEntry]> all-logs;
    in-out property <[string]> upstream-servers;
    in-out property <[string]> rule-list;

    // 回调
    callback start-dns();
    callback stop-dns();
    callback start-tun();
    callback stop-tun();
    callback save-dns-settings(string, bool, int, int);
    callback save-advanced-settings();
    callback clear-logs();
    callback export-logs();
    callback import-rules();
    callback export-rules();

    HorizontalLayout {
        // 侧边栏
        SideBar {
            current-page: current-page;
            page-changed(page) => {
                current-page = page;
            }
        }

        // 主内容区
        if current-page == 0: DashboardPage {
            total-queries: total-queries;
            blocked-queries: blocked-queries;
            cached-queries: cached-queries;
            avg-latency: avg-latency;
            dns-running: dns-running;
            tun-running: tun-running;
            memory-usage: memory-usage;
            recent-logs: recent-logs;
            start-dns => { start-dns(); }
            stop-dns => { stop-dns(); }
            start-tun => { start-tun(); }
            stop-tun => { stop-tun(); }
        }

        if current-page == 1: DnsSettingsPage {
            listen-port: listen-port;
            auto-start: auto-start;
            cache-size: cache-size;
            cache-ttl: cache-ttl;
            upstream-servers: upstream-servers;
            save-settings(port, auto, size, ttl) => {
                save-dns-settings(port, auto, size, ttl);
            }
        }

        if current-page == 2: RulesPage {
            total-rules: total-rules;
            block-rules: block-rules;
            allow-rules: allow-rules;
            rule-list: rule-list;
            import-rules => { import-rules(); }
            export-rules => { export-rules(); }
        }

        if current-page == 3: LogsPage {
            logs: all-logs;
            clear-logs => { clear-logs(); }
            export-logs => { export-logs(); }
        }

        if current-page == 4: AdvancedSettingsPage {
            enable-tun: enable-tun;
            tun-interface: tun-interface;
            tun-gateway: tun-gateway;
            save-advanced-settings => { save-advanced-settings(); }
        }
    }
}

toolUseResult.content:
import { Button, VerticalBox, HorizontalBox, LineEdit, CheckBox, ScrollView, GroupBox, Switch } from "std-widgets.slint";

// 颜色主题 - 现代深色主题
global Theme {
    in-out property <color> bg-primary: #0f0f14;
    in-out property <color> bg-secondary: #16161e;
    in-out property <color> bg-card: #1e1e28;
    in-out property <color> bg-hover: #252530;
    in-out property <color> text-primary: #e8e8ed;
    in-out property <color> text-secondary: #8888a0;
    in-out property <color> text-muted: #555568;
    in-out property <color> accent: #7c5cfc;
    in-out property <color> accent-light: #9070ff;
    in-out property <color> success: #00d68f;
    in-out property <color> success-light: #00d68f40;
    in-out property <color> warning: #ffaa00;
    in-out property <color> error: #ff4466;
    in-out property <color> error-light: #ff446640;
    in-out property <color> border: #2a2a38;
}

// DNS日志条目
struct DnsLogEntry {
    timestamp: string,
    domain: string,
    query-type: string,
    response: string,
    status: string,
    latency: string,
}

// 侧边栏组件
component SideBar inherits Rectangle {
    in-out property <int> current-page: 0;
    callback page-changed(int);

    width: 220px;
    background: Theme.bg-secondary;

    VerticalLayout {
        // Logo区域
        Rectangle {
            height: 80px;
            background: Theme.bg-primary;

            Text {
                text: "⚡ DNS Proxy";
                font-size: 22px;
                font-weight: 800;
                color: Theme.text-primary;
                horizontal-alignment: center;
                vertical-alignment: center;
            }
        }

        Rectangle { height: 1px; background: Theme.border; }

        Rectangle { height: 16px; }

        // 菜单项
        for page[index] in [
            { icon: "📊", label: "仪表盘" },
            { icon: "⚙️", label: "DNS 设置" },
            { icon: "📋", label: "规则管理" },
            { icon: "📡", label: "查询日志" },
            { icon: "🔧", label: "高级设置" },
        ]: Rectangle {
            height: 48px;
            background: current-page == index ? Theme.accent : transparent;
            border-radius: 10px;

            touch := TouchArea {
                clicked => {
                    current-page = index;
                    page-changed(index);
                }
            }

            HorizontalLayout {
                spacing: 12px;
                padding-left: 20px;

                Text {
                    text: page.icon;
                    font-size: 18px;
                    vertical-alignment: center;
                }

                Text {
                    text: page.label;
                    font-size: 14px;
                    font-weight: current-page == index ? 600 : 400;
                    color: current-page == index ? white : Theme.text-primary;
                    vertical-alignment: center;
                }
            }
        }

        Rectangle { vertical-stretch: 1; }

        // 底部状态
        Rectangle {
            height: 60px;
            background: Theme.bg-primary;

            Rectangle { height: 1px; background: Theme.border; y: 0px; }

            Text {
                text: "● 服务运行中";
                font-size: 12px;
                color: Theme.success;
                horizontal-alignment: center;
                vertical-alignment: center;
            }
        }
    }
}

// 统计卡片
component StatCard inherits Rectangle {
    in property <string> title;
    in property <string> value;
    in property <string> icon;
    in property <color> icon-color: Theme.accent;
    in property <color> value-color: Theme.text-primary;

    background: Theme.bg-card;
    border-radius: 16px;
    border-width: 1px;
    border-color: Theme.border;
    min-height: 120px;

    VerticalLayout {
        padding: 20px;
        spacing: 12px;

        HorizontalLayout {
            spacing: 10px;

            Rectangle {
                width: 36px;
                height: 36px;
                border-radius: 10px;
                background: icon-color;

                Text {
                    text: icon;
                    font-size: 18px;
                    horizontal-alignment: center;
                    vertical-alignment: center;
                }
            }

            Text {
                text: title;
                font-size: 13px;
                color: Theme.text-secondary;
                vertical-alignment: center;
            }
        }

        Text {
            text: value;
            font-size: 32px;
            font-weight: 700;
            color: value-color;
        }
    }
}

// 状态卡片（带开关）
component StatusCard inherits Rectangle {
    in property <string> title;
    in property <string> subtitle;
    in property <bool> active: false;
    in property <string> icon;
    callback toggle();

    background: Theme.bg-card;
    border-radius: 16px;
    border-width: 1px;
    border-color: active ? Theme.success-light : Theme.border;
    min-height: 100px;

    HorizontalLayout {
        padding: 20px;
        spacing: 16px;

        Rectangle {
            width: 48px;
            height: 48px;
            border-radius: 12px;
            background: active ? Theme.success : Theme.error;

            Text {
                text: icon;
                font-size: 24px;
                horizontal-alignment: center;
                vertical-alignment: center;
            }
        }

        VerticalLayout {
            alignment: center;
            spacing: 4px;
            horizontal-stretch: 1;

            Text {
                text: title;
                font-size: 16px;
                font-weight: 600;
                color: Theme.text-primary;
            }

            Text {
                text: subtitle;
                font-size: 13px;
                color: active ? Theme.success : Theme.text-secondary;
            }
        }

        Switch {
            checked: active;
            toggled => {
                toggle();
            }
        }
    }
}

// 仪表盘页面
component DashboardPage inherits ScrollView {
    in property <int> total-queries: 0;
    in property <int> blocked-queries: 0;
    in property <int> cached-queries: 0;
    in property <float> avg-latency: 0;
    in property <bool> dns-running: false;
    in property <bool> tun-running: false;
    in property <int> memory-usage: 0;
    in property <[DnsLogEntry]> recent-logs;

    callback start-dns();
    callback stop-dns();
    callback start-tun();
    callback stop-tun();

    VerticalLayout {
        padding: 24px;
        spacing: 20px;

        Text {
            text: "仪表盘";
            font-size: 28px;
            font-weight: 700;
            color: Theme.text-primary;
        }

        // 状态卡片
        HorizontalLayout {
            spacing: 16px;

            StatusCard {
                title: "DNS 服务";
                subtitle: dns-running ? "运行中 - 监听端口 53" : "已停止";
                active: dns-running;
                icon: "🌐";
                horizontal-stretch: 1;
                toggle => {
                    if dns-running {
                        stop-dns();
                    } else {
                        start-dns();
                    }
                }
            }

            StatusCard {
                title: "TUN 模式";
                subtitle: tun-running ? "运行中 - 全局代理" : "已停止";
                active: tun-running;
                icon: "🔒";
                horizontal-stretch: 1;
                toggle => {
                    if tun-running {
                        stop-tun();
                    } else {
                        start-tun();
                    }
                }
            }
        }

        // 统计卡片
        HorizontalLayout {
            spacing: 16px;

            StatCard {
                title: "总查询";
                value: total-queries;
                icon: "📊";
                icon-color: Theme.accent;
                horizontal-stretch: 1;
            }

            StatCard {
                title: "已阻止";
                value: blocked-queries;
                icon: "🛡️";
                icon-color: Theme.error;
                value-color: Theme.error;
                horizontal-stretch: 1;
            }

            StatCard {
                title: "缓存命中";
                value: cached-queries;
                icon: "⚡";
                icon-color: Theme.success;
                value-color: Theme.success;
                horizontal-stretch: 1;
            }

            StatCard {
                title: "平均延迟";
                value: avg-latency + "ms";
                icon: "⏱️";
                icon-color: Theme.warning;
                horizontal-stretch: 1;
            }
        }

        // 最近日志
        Rectangle {
            background: Theme.bg-card;
            border-radius: 16px;
            border-width: 1px;
            border-color: Theme.border;
            min-height: 300px;

            VerticalLayout {
                padding: 20px;
                spacing: 12px;

                Text {
                    text: "最近查询";
                    font-size: 16px;
                    font-weight: 600;
                    color: Theme.text-primary;
                }

                Rectangle { height: 1px; background: Theme.border; }

                for log in recent-logs: Rectangle {
                    height: 40px;
                    border-radius: 8px;
                    background: touch.has-hover ? Theme.bg-hover : transparent;

                    touch := TouchArea {}

                    HorizontalLayout {
                        spacing: 16px;
                        padding-left: 12px;
                        padding-right: 12px;

                        Text {
                            text: log.timestamp;
                            font-size: 12px;
                            color: Theme.text-muted;
                            width: 80px;
                            vertical-alignment: center;
                        }

                        Text {
                            text: log.domain;
                            font-size: 13px;
                            color: Theme.text-primary;
                            horizontal-stretch: 1;
                            overflow: elide;
                            vertical-alignment: center;
                        }

                        Rectangle {
                            width: 60px;
                            height: 24px;
                            border-radius: 6px;
                            background: log.status == "已阻止" ? Theme.error-light : Theme.success-light;
                            vertical-alignment: center;

                            Text {
                                text: log.status;
                                font-size: 11px;
                                font-weight: 500;
                                color: log.status == "已阻止" ? Theme.error : Theme.success;
                                horizontal-alignment: center;
                                vertical-alignment: center;
                            }
                        }

                        Text {
                            text: log.latency;
                            font-size: 12px;
                            color: Theme.text-muted;
                            width: 60px;
                            horizontal-alignment: right;
                            vertical-alignment: center;
                        }
                    }
                }
            }
        }
    }
}

// DNS设置页面
component DnsSettingsPage inherits ScrollView {
    in property <string> listen-port: "53";
    in property <bool> auto-start: true;
    in property <int> cache-size: 5000;
    in property <int> cache-ttl: 1800;
    in property <[string]> upstream-servers;

    callback save-settings(string, bool, int, int);

    VerticalLayout {
        padding: 24px;
        spacing: 20px;

        Text {
            text: "DNS 设置";
            font-size: 28px;
            font-weight: 700;
            color: Theme.text-primary;
        }

        // 监听配置
        Rectangle {
            background: Theme.bg-card;
            border-radius: 16px;
            border-width: 1px;
            border-color: Theme.border;

            VerticalLayout {
                padding: 24px;
                spacing: 20px;

                Text {
                    text: "🌐 监听配置";
                    font-size: 18px;
                    font-weight: 600;
                    color: Theme.text-primary;
                }

                Rectangle { height: 1px; background: Theme.border; }

                HorizontalLayout {
                    spacing: 16px;

                    VerticalLayout {
                        spacing: 8px;
                        horizontal-stretch: 1;

                        Text {
                            text: "监听端口";
                            font-size: 13px;
                            color: Theme.text-secondary;
                        }

                        LineEdit {
                            text: listen-port;
                            height: 44px;
                        }
                    }

                    VerticalLayout {
                        spacing: 8px;

                        Text {
                            text: "自动启动";
                            font-size: 13px;
                            color: Theme.text-secondary;
                        }

                        Switch {
                            checked: auto-start;
                        }
                    }
                }
            }
        }

        // 缓存配置
        Rectangle {
            background: Theme.bg-card;
            border-radius: 16px;
            border-width: 1px;
            border-color: Theme.border;

            VerticalLayout {
                padding: 24px;
                spacing: 20px;

                Text {
                    text: "⚡ 缓存配置";
                    font-size: 18px;
                    font-weight: 600;
                    color: Theme.text-primary;
                }

                Rectangle { height: 1px; background: Theme.border; }

                HorizontalLayout {
                    spacing: 16px;

                    VerticalLayout {
                        spacing: 8px;
                        horizontal-stretch: 1;

                        Text {
                            text: "缓存大小";
                            font-size: 13px;
                            color: Theme.text-secondary;
                        }

                        LineEdit {
                            text: cache-size;
                            height: 44px;
                        }
                    }

                    VerticalLayout {
                        spacing: 8px;
                        horizontal-stretch: 1;

                        Text {
                            text: "缓存 TTL (秒)";
                            font-size: 13px;
                            color: Theme.text-secondary;
                        }

                        LineEdit {
                            text: cache-ttl;
                            height: 44px;
                        }
                    }
                }
            }
        }

        // 上游服务器
        Rectangle {
            background: Theme.bg-card;
            border-radius: 16px;
            border-width: 1px;
            border-color: Theme.border;

            VerticalLayout {
                padding: 24px;
                spacing: 16px;

                HorizontalLayout {
                    Text {
                        text: "🌍 上游 DNS 服务器";
                        font-size: 18px;
                        font-weight: 600;
                        color: Theme.text-primary;
                        vertical-alignment: center;
                    }

                    Rectangle { horizontal-stretch: 1; }

                    Button {
                        text: "+ 添加服务器";
                        width: 120px;
                    }
                }

                Rectangle { height: 1px; background: Theme.border; }

                for server in upstream-servers: Rectangle {
                    height: 52px;
                    border-radius: 10px;
                    background: Theme.bg-hover;
                    border-width: 1px;
                    border-color: Theme.border;

                    HorizontalLayout {
                        padding-left: 16px;
                        padding-right: 16px;

                        Text {
                            text: server;
                            font-size: 14px;
                            color: Theme.text-primary;
                            vertical-alignment: center;
                            horizontal-stretch: 1;
                        }

                        Button {
                            text: "删除";
                            width: 70px;
                        }
                    }
                }
            }
        }

        // 保存按钮
        HorizontalLayout {
            alignment: end;

            Button {
                text: "保存设置";
                width: 140px;
                height: 44px;
                clicked => {
                    save-settings(listen-port, auto-start, cache-size, cache-ttl);
                }
            }
        }
    }
}

// 规则管理页面
component RulesPage inherits ScrollView {
