                    border-radius: 8px;

                    HorizontalLayout {
                        padding-left: 16px;
                        padding-right: 16px;
                        spacing: 16px;

                        Text {
                            text: "时间";
                            font-size: 12px;
                            font-weight: 600;
                            color: Theme.text-secondary;
                            width: 80px;
                            vertical-alignment: center;
                        }

                        Text {
                            text: "域名";
                            font-size: 12px;
                            font-weight: 600;
                            color: Theme.text-secondary;
                            horizontal-stretch: 1;
                            vertical-alignment: center;
                        }

                        Text {
                            text: "类型";
                            font-size: 12px;
                            font-weight: 600;
                            color: Theme.text-secondary;
                            width: 50px;
                            vertical-alignment: center;
                        }

                        Text {
                            text: "状态";
                            font-size: 12px;
                            font-weight: 600;
                            color: Theme.text-secondary;
                            width: 70px;
                            horizontal-alignment: center;
                            vertical-alignment: center;
                        }

                        Text {
                            text: "延迟";
                            font-size: 12px;
                            font-weight: 600;
                            color: Theme.text-secondary;
                            width: 70px;
                            horizontal-alignment: right;
                            vertical-alignment: center;
