                    HorizontalLayout {
                        padding-left: 16px;
                        padding-right: 16px;
                        spacing: 16px;

                        Text {
                            text: log.timestamp;
                            font-size: 12px;
                            color: Theme.text-muted;
                            width: 80px;
                            vertical-alignment: center;
